INSERT INTO game_system_changes VALUES(1,'FC26','engine','역할 커널은 결정적이지 않다 — EA가 역할 구속을 의도적으로 완화("less constrained by their Roles", 모든 역할 위치 조정)','EA Gameplay Deep Dive 원문 인용 (docs/20 ①)','적합도 Δ 0.02~0.05는 노이즈 구간 — 그 차이로 인선을 가르지 않는다(obs#91). 방법론의 구조적 상한','EA 피치노트','HIGH — 1차 자료','2026-08-11','역할 커널은 결정적이지 않다 — EA가 역할 구속을 완화');
INSERT INTO game_system_changes VALUES(2,'FC26','roles','숙련도(Role+/++) 격차 축소 + Out of Position 페널티 대폭 감소','EA 원문 "bring them closer to Roles++" (docs/20 ②)','미숙련 회피에 큰 적합도를 지불하지 말 것. Δ≤.05면 숙련 우선, 크면 적합 우선(절충)','EA 피치노트','HIGH','2026-08-11','Role+/++ 격차·포지션 이탈 페널티 축소');
INSERT INTO game_system_changes VALUES(3,'FC26','roles','역할·포커스 개명 — Wide Mid Balanced→Support 등 (FC25 표기와 동일 실체)','docs/20 ③ 대조표','문서 인용 시 표기 혼동 방지','EA/fut.gg','HIGH','2026-08-11','역할·포커스 개명(FC25 표기와 같은 실체)');
INSERT INTO game_system_changes VALUES(4,'FC26','positioning','Wide Mid 리워크 — 수비 지향·백3 최적화("ideal for 3-back formations")','EA 원문 + 커널 자기진영 질량(Defend 1.30/Support 0.60) (docs/20 ④)','에메리 뱅크 칸=Support 기본. 알론소 3-4-2-1에는 최적, 백4 정합성은 미확인','EA 피치노트','HIGH','2026-08-11','와이드 미드 리워크 — 수비 지향·백3 최적화');
INSERT INTO game_system_changes VALUES(5,'FC26','attributes','AcceleRATE 3종 회귀(Explosive/Lengthy/Controlled) — 2차 속성은 힘(Strength)','전수 대조 20명, 힘 16/20 (obs#104, docs/20 ⑤)','sofifa 수집값 교차검증용. 효과 크기는 비공개라 적합 가중치로는 못 씀','EA+실측 대조','HIGH','2026-08-11','AcceleRATE 3종 복귀(2차 속성은 힘)');
INSERT INTO game_system_changes VALUES(6,'FC26','tactics','Team Press 수비 진영 너프(2026-05-28) — 진영별 비대칭 압박','EA TU 원문 (docs/20 ⑥)','고압박(이라올라)이 가장 불리, 에메리 미드블록 상대적 유리. 압박은 라인+수비접근으로 근사','EA 피치노트','HIGH','2026-08-11','팀 압박 수비 진영 너프');
INSERT INTO game_system_changes VALUES(7,'FC26','meta','선수 행동 = OVR + HyperMotion + PlayStyles(온더볼) + Roles(오프더볼) — 커널은 Roles 층에만 대응','obs#87·#88·#90, 히트맵이 요구역할의 36.2%만 담음(obs#121)','실측 재현의 층위 한계를 명시 — 온더볼은 PlayStyles·스탯 레버','EA+실측','HIGH','2026-08-11','선수 행동의 4층 구조 — 커널은 역할 층만 다룬다');
INSERT INTO game_system_changes VALUES(8,'FC26','meta','미검증 잔여: 라인 높이 실효 / TU 1.1~1.3 원문 404 / Role++·OOP 정량','docs/20 ⑦','추정을 하드 제약으로 쓰지 않는다','—','기록','2026-08-11','FC26 미검증 잔여 항목');
INSERT INTO game_system_changes VALUES(9,'FC26','positioning','윙 혼잡 회피 조정 — 와이드미드·풀백 공격 역할의 위치를 「측면 혼잡을 피하도록」 조정 + 윙백 전진은 「앞에 빈 공간이 있을 때」 발동','EA Gameplay Deep Dive: 「Tweaked Wide Mids and Fullbacks attacking Roles'' positions to avoid congestion in the wings」(측면 혼잡을 피하기 위해 윙 미드필더와 풀백의 공격 역할 위치를 조정했다)(FC IQ) · 「a Wingback can move forward if there is open space in front of them」(윙백은 앞에 열린 공간이 있으면 전진할 수 있다)(Positioning). 역할 정의: att_wb/Support=「rarely sprint back」(복귀 감소), att_wb/Attack=「push even higher」(전진 강화), insidefwd/Attack=「cutting inside」(측면 비움).','풀백 전진은 같은 쪽 와이드 역할이 결정한다 — 터치라인형(winger·widemid·wideplm) 뒤의 풀백은 올라가지 않으므로 wingback/Balanced로 두고, 전진시킬 풀백의 앞은 안쪽형 와이드로 비운다(C6와 결합: 윙어는 절제 사이드). 「풀백을 올리려고 양쪽 att_wb/Support」는 정의·메커니즘·C2 모두 위반. obs#443.','EA 피치노트 1차(2026-09-04 직독) · game_role_focus · obs#443','EA 문장 HIGH · 효과 크기 비공개 · 인게임 A/B 미실시','2026-09-04','측면 혼잡 회피 — 윙백 전진은 앞이 비었을 때만');
INSERT INTO game_system_changes VALUES(10,'FC27','roles','⭐ Attacking Spatial Awareness — 「Roles가 너무 엄격하게 느껴진다」는 진단에 EA가 내놓은 해법. AI 공격수가 주변 공간을 인식해 곡선 침투(Triggered Curved Runs)·Pass & Follow Runs로 움직인다. ⛔ 역할·포커스의 신설/삭제/개명은 어느 피치노트에도 없다(2026-09-04 기준 미공개).','FUT Deep Dive: 「Roles can sometimes feel too strict in gameplay, so in FC 27 we are introducing Attacking Spatial Awareness to help players recognise open space more naturally and make more decisive runs in attack.」(역할이 게임플레이에서 때로 너무 엄격하게 느껴질 수 있어서, FC 27에서는 선수들이 열린 공간을 더 자연스럽게 인지하고 공격에서 더 결단력 있게 달리도록 돕는 공격 공간 인지를 도입한다.) · Gameplay Deep Dive: 「makes AI attackers more aware of the space around them and how they move into it. … attackers would also run into crowded areas or struggle to find more effective space. In FC 27, they now make smarter, more contextual curved runs」(AI 공격수가 주변 공간과 그곳으로 움직이는 방식을 더 잘 인지하게 한다… 공격수가 혼잡한 지역으로 달려가거나 더 효과적인 공간을 찾지 못하는 경우도 있었다. FC 27에서는 이제 더 영리하고 상황에 맞는 곡선 주행을 한다) · 조작: 곡선 런 Tap L1+R1 / Pass&Follow L1+R1+X.','FC26 ①(「less constrained by their Roles」(역할의 제약을 덜 받는))의 연장·강화 — **역할 커널의 결정성이 한 단계 더 약해진다**. 우리 코사인 적합의 구조적 상한이 더 내려가므로 FC27 커널에서는 노이즈 구간(Δ≤0.05)을 넓게 볼 근거가 생긴다(크기는 실측 후 결정). ⚠️ 37/85/217 구조가 유지되는지는 fut.gg /api/fut/roles/ FC27 응답으로만 확정 — Kernel.EXPECTED 확장은 그때.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive (2026-07-29) · https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-fut-deep-dive','EA 1차 verbatim(HIGH) · 역할 목록 변화 여부는 미확인(UNKNOWN)','2026-09-04','공격 공간 인식(곡선 침투) 도입 — 역할 개편은 없음');
INSERT INTO game_system_changes VALUES(11,'FC27','engine','Triggered Runs 거리 제한 — 한 번의 트리거로 달리는 거리가 제한되고, 계속 달리게 하려면 다시 트리거해야 한다(클로즈드 베타 피드백 반영).','Beta Feedback Update: 「Triggered Runs will now have a limited distance. You''ll need to trigger another run if you want the player [to continue]」(발동형 주행은 이제 거리가 제한된다. 선수가 계속 달리게 하려면 다시 주행을 발동해야 한다) — 「reduces some of the benefits Lengthy players could gain over extended distances」(렝시 유형 선수가 장거리에서 얻을 수 있던 이점을 일부 줄인다).','채널 러너형(st_advanced/Support·wm_winger/Attack)의 게임 내 침투 거리가 짧아진다 — 실측 「배후 침투」 서사를 게임에 옮길 때 한 번의 런으로 재현되지 않을 수 있음. 경기 프리셋 설명에 「런 재트리거 필요」 메모.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH) · 거리 수치 비공개','2026-09-04','트리거 침투 거리 제한');
INSERT INTO game_system_changes VALUES(12,'FC27','attributes','AcceleRATE 영향 축소 — Explosive/Controlled/Lengthy 간 차이를 줄이고 가속력·질주속도 속성 비중을 높임. 여성 Lengthy 키 하한 172cm(5''8").','Beta Feedback Update: 「We''ve slightly reduced the impact of AcceleRATE profiles on a player''s running performance, bringing Explosive, Controlled, and Lengthy players a little closer together … greater emphasis on a player''s Acceleration and Sprint Speed Attributes」(가속 프로필이 선수의 달리기 성능에 미치는 영향을 약간 줄여 익스플로시브, 컨트롤드, 렝시 선수를 조금 더 가깝게 만들었다… 선수의 가속력과 스프린트 속도 능력치를 더 크게 강조한다) · 「female players will need to be at least 5''8" (172 cm) to be eligible for Lengthy」(여자 선수는 렝시 자격을 얻으려면 최소 5피트 8인치 172cm 이상이어야 한다).','docs/20 ⑤ 분류 공식(남 183cm 등)은 유지되나 **효과 크기가 줄어** 적합 가중치로 쓸 이유가 더 없어진다. 남성 임계값 변경 언급 없음 — 09-25 이후 sofifa/fut.gg accelerate 라벨 재대조 필요.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH) · 남성 임계값 불변 여부 미확인','2026-09-04','AcceleRATE 영향 축소');
INSERT INTO game_system_changes VALUES(13,'FC27','playstyles','PlayStyle 리밸런스 10종 + PlayStyle+ 상한 5→3(아이템당). Finesse Shot(속성 비중↑) · Technical(+와 격차↓) · Intercept(리치↑·소유 유지↑) · Rapid(드리블 속도 보너스↓) · Quick Step(가속 보너스↓) · Pinged Pass(수신자 트랩 오차 감소 효과 제거) · Tiki Taka(애니 속도 보너스·트랩 오차 감소 제거) · Jockey(비보유자 조키 가속↑·보너스↓) · Precision Header(정확도 보너스 재조정) · Low Driven(슛 속도 보너스 제거). Bruiser+ 추가 이득 소폭 축소.','Gameplay Deep Dive 각 항목 verbatim: 「We''ve updated Finesse Shot to make player attributes play a bigger role in shot outcome」(선수 능력치가 슛 결과에 더 큰 역할을 하도록 피네스 슛을 개선했다) · 「Removed the effect that slightly reduced trap error on the pass receiver」(패스 받는 선수의 트랩 오차를 약간 줄이던 효과를 제거했다)(Pinged Pass) · 「Removed the animation playback speed boost and the effect that slightly reduced trap error」(애니메이션 재생 속도 증가와 트랩 오차를 약간 줄이던 효과를 제거했다)(Tiki Taka) · 「Removed the shot speed boost previously applied to low-driven shots」(로우 드리븐 슛에 적용되던 슛 속도 증가를 제거했다) · FUT Deep Dive: 「reducing the maximum number of PlayStyle+ available on a single Item from five to three」(한 아이템에서 사용할 수 있는 플레이스타일 플러스의 최대 개수를 다섯 개에서 세 개로 줄였다) · Beta: 「slightly reduced the additional benefit provided by Bruiser+」(브루저 플러스가 주는 추가 이점을 약간 줄였다). 신설·삭제 PlayStyle 언급 없음.','docs/22 §3 카탈로그(35종)는 이름은 유지되되 **효과 서술 10건을 FC27 절로 갱신**해야 한다(특히 Pinged Pass·Tiki Taka의 「받기 쉬워짐」 문구는 FC27에서 거짓). player_game_stats.playstyles 해석 시 버전 주의. 온볼 층이라 커널 무관.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive (2026-07-29) · https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-fut-deep-dive · https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH) · 09-10 전체 DB 공개 시 신설/삭제 재확인','2026-09-04','PlayStyle 10종 리밸런스 · PS+ 상한 3');
INSERT INTO game_system_changes VALUES(14,'FC27','tactics','Team Press — 자기 수비 3분의 1에서는 효과 없음(FC26 ⑥ 「수비 진영 너프」의 완성형). 낮은 수비 깊이 설정이 라인 위치에 더 뚜렷하게 반영.','Beta Feedback Update: 「Team Press will now have no effect while the ball is in your defensive third」(볼이 우리 수비 3분의 1 지역에 있을 때 팀 압박은 이제 아무 효과도 없다) · 「defenders can still step towards their marked players, but will be less effective at applying pressure」(수비수는 여전히 마크 상대에게 다가갈 수 있지만 압박을 가하는 효과는 떨어진다) · 「lower depth settings are more clearly reflected in how your defensive line positions itself」(낮은 수비 라인 깊이 설정이 수비 라인이 위치를 잡는 방식에 더 분명하게 반영된다).','FC26 ⑥의 진영별 비대칭이 **수비 3분의 1 완전 무효**로 굳어진다 — 이라올라(고압박) 재현 손실이 더 커지고, 에메리 딥블록 국면(PPDA 30 계열)은 게임에서 「팀 프레스 없음 + 낮은 깊이」로 오히려 정확히 재현된다. 라인 높이 실효(FC26 ⑦ 미검증)는 FC27에서 「더 뚜렷」해진다는 EA 진술 — 재검증 우선순위 상향.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH) · 수치 비공개','2026-09-04','팀 압박 — 자기 수비 3분의 1에서 무효');
INSERT INTO game_system_changes VALUES(15,'FC27','engine','수동 수비 강화(Competitive 전용) — AI 수비수 인터셉트 리치 축소, 수동 조작 수비수 조키 속도↑·스탠딩 태클 범위↑. AI 수비수는 「포지셔닝 지원 역할」로.','Gameplay Deep Dive: 「we''re reducing the influence of AI-controlled defenders, putting more power into the hands of the manual defender」(AI가 조종하는 수비수의 영향력을 줄이고 수동 수비수에게 더 큰 힘을 실어주고 있다) · 「We''ve also reduced AI defensive reach for interceptions」(인터셉트에 대한 AI 수비 범위도 줄였다) · 「manually-controlled defenders have increased jockey speed」(수동 조작 수비수의 재키 속도가 증가했다) · 「increased the range of manually-triggered stand tackles」(수동으로 발동하는 스탠드 태클의 범위를 늘렸다) · 「The following changes to AI Defending only apply to Competitive gameplay」(AI 수비에 대한 다음 변경 사항은 경쟁 게임플레이에만 적용된다).','수비 역할(cb_*/dm_holding)의 **AI 실행력이 낮아진다** — 커널(위치)은 그대로지만 「막아내는 결과」는 사용자 조작 의존. Intercept PlayStyle은 반대로 강화(#13) — AI 수비 재현은 PlayStyle 층으로 보상. Authentic(커리어)에는 미적용.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive (2026-07-29)','EA 1차 verbatim(HIGH)','2026-09-04','수동 수비 강화(AI 수비 리치 축소)');
INSERT INTO game_system_changes VALUES(16,'FC27','engine','Dinked Pass 완전 수동 — Ground Pass 입력으로는 불가(더블탭=일반 그라운드 패스), Through Pass 더블탭 + 수동 조준. Player Lock 시 볼 캐리어 자동 회피 제거·CPU 패스 오차↑.','Beta Feedback Update: 「Dinked Passes can no longer be performed using the Ground Pass input」(딩크 패스는 더 이상 땅볼 패스 입력으로 수행할 수 없다) · 「double tap Through Pass and manually aim where you want the ball to go」(스루 패스를 두 번 눌러 공이 가길 원하는 곳을 직접 조준한다) · 「the ball carrier will no longer automatically dribble around or avoid defenders」(볼 소유자는 더 이상 수비수를 자동으로 돌아가거나 피하지 않는다)(Player Lock).','docs/22 §1 조작표 갱신 대상(FC27 절). 전술 재현과 무관한 조작 층.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH)','2026-09-04','딩크 패스 완전 수동화');
INSERT INTO game_system_changes VALUES(17,'FC27','meta','커리어 모드 — 선수당 최대 7포지션(주 1 + 부 6), 부 포지션에서는 OOP 페널티 없음, Dynamic OVR(폼·사기·경기체력), 포지션별 Baseline OVR 부활, 성장 프로필 6종, 슬라이더 25+10(CPU 상대/동료 분리). Authentic: CPU 전술 다양화·피지컬 접촉 강화·CPU 파울 증가.','Career Deep Dive: 「Players will now have up to seven positions they can perform in」(선수는 이제 최대 일곱 개의 포지션에서 뛸 수 있다) · 「Players performing in any of their six secondary preferred positions will not be penalised for playing outside their main position」(여섯 개의 보조 선호 포지션 중 어느 곳에서 뛰어도 주 포지션 밖에서 뛴다는 불이익을 받지 않는다) · 「dynamic determination of a player''s Baseline OVR based on the position they play in」(선수가 뛰는 포지션에 따른 기본 OVR의 동적 결정) · 「Six distinct Growth Profiles」(여섯 가지 뚜렷한 성장 프로필) · 「CPU-controlled players will also commit more fouls」(CPU가 조종하는 선수도 파울을 더 많이 범한다).','**포지션 유연성이 게임 데이터 축으로 들어온다** — FC26 ②(OOP 페널티 대폭 감소)에서 한 발 더 나가 부 포지션은 무페널티. 우리 「측정 최적 ≠ EA 기본 포지션」 사례(맥긴 RM, 캐시 att_wb 등)의 게임 내 비용이 더 낮아진다. 커리어 축 데이터(7포지션 목록)는 09-10 DB에서 수집 대상 — player_game_stats.positions 해석 갱신.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-career-mode-deep-dive (2026-07-31)','EA 1차 verbatim(HIGH) · 숙련도 산식은 비공개','2026-09-04','커리어 모드 포지션·OVR 체계 변경');
INSERT INTO game_system_changes VALUES(18,'FC27','meta','출시 초기 밸런스 정책 — 「초기 타이틀 업데이트에서 큰 게임플레이 밸런스 변경을 하지 않는다」. 발매 09-25(얼리액세스 09-18). ⛔ 역할 목록·팀 전술 파라미터 변화는 어느 피치노트에도 없음.','Beta Feedback Update: 「we do not plan on making significant gameplay balance changes in our early Title Updates」(초기 타이틀 업데이트에서는 큰 게임플레이 밸런스 변경을 계획하고 있지 않다) · 「we don''t want to react quickly to early trends with significant balance changes」(초기 경향에 큰 밸런스 변경으로 빠르게 반응하고 싶지 않다).','FC27 커널·파라미터 수집을 **발매 직후 1회로 잡아도 초기 TU로 흔들릴 위험이 작다**(FC26은 TU 1.4/1.5가 역할 위치를 바꿨다 — docs/20 ①). 역할 목록 미공개 상태이므로 09-18 얼리액세스 시점의 fut.gg /api/fut/roles/ 응답이 마이그레이션 트리거.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','EA 1차 verbatim(HIGH)','2026-09-04','출시 초기 밸런스 동결 정책(예고)');
INSERT INTO game_system_changes VALUES(19,'FC27','roles','⭐ 역할은 유지된다 — Attacking Spatial Awareness는 역할을 대체하지 않고 **함께 작동**한다. 「roles still determining which runs a player can make from their position」(역할은 여전히 그 선수가 자기 위치에서 어떤 침투를 할 수 있는지를 결정한다).','FC27 게임플레이 딥다이브·베타 피드백 정리 기사 (2026-09-19 D+0 확인)','우리 역할 커널의 **존재 근거가 유지**된다 — 다만 공간 인식이 겹치면서 같은 역할에서도 움직임 분산이 커지므로 Δ 노이즈 구간을 FC26보다 넓게 잡을 근거가 된다(크기는 FC27 실측 후).','ea.com FC27 gameplay deep dive · closed beta feedback update (2차 정리 기사 경유)','MEDIUM-HIGH — EA 1차 진술의 2차 인용','2026-09-19','역할은 유지 — 공간 인식과 함께 작동');
INSERT INTO game_system_changes VALUES(20,'FC27','tactics','Team Press는 **수비 3분의 1에서 무효**이고, 그 위에서도 **수비수는 미드필더·공격수보다 압박 효율이 낮다**. 팀메이트 컨테인도 완화 — AI 동료가 볼 캐리어를 더 먼 거리에서 마크한다(수동 전환 필요).','베타 피드백 업데이트 정리 — 「defenders press less effectively than midfielders and forwards」(수비수는 미드필더와 공격수보다 압박 효과가 떨어진다)','에메리 재현에 **유리**하다: 미드블록에서 중원이 먼저 걸고 백4는 자리를 지키는 구조가 게임 기본 동작이 된다. ⚠️ 반대로 RCB Aggressive의 step-out 빈도는 FC26보다 줄 수 있다 — 실측 관찰 항목.','ea.com FC27 closed beta feedback update (2차 정리 기사 경유, 2026-09-19 확인)','MEDIUM-HIGH','2026-09-19','팀 압박 수비수 효율 저하 · 동료 컨테인 완화');
INSERT INTO game_system_changes VALUES(21,'FC27','meta','프로모 선수는 **base 포지션에 Role++를 기본 보유**한다(런치 업데이트). PlayStyle+ 상한은 3으로 확정.','FC27 Launch Update 피치노트 정리 — 「All promo players will have Role++ for their base positions」(모든 프로모 선수는 기본 포지션에서 롤 플러스 플러스를 갖는다)','진화·카드 선택 기준이 바뀐다 — 프로모 카드는 처방 역할이 base 포지션과 맞으면 **숙련(Role++)이 자동 충족**된다. 진화로 Role++를 얻으러 갈 이유가 줄고, PS+ 상한 3 때문에 PlayStyle+ 획득 진화의 상대 가치가 오른다.','FC27 Launch Update pitch notes (2차 정리, 2026-09-19 확인)','MEDIUM — 2차 인용. fut.gg 카드 데이터로 교차검증 필요','2026-09-19','프로모 선수 Role++ 기본 보유 · PS+ 상한 3 확정');
INSERT INTO game_system_changes VALUES(22,'FC27','playstyles','⭐⭐ 패서의 PlayStyle이 리시버의 퍼스트 터치를 덮어주던 경로가 끊겼다 — 핑드 패스·티키타카에서 「패스 수신자의 트랩 오차를 약간 줄여주던 효과」가 제거됐다. 티키타카는 애니메이션 재생 속도 부스트도 함께 잃었다.','원문 「Pinged Pass — Removed the effect that slightly reduced trap error on the pass receiver. This change ensures that the PlayStyle primarily enhances pass delivery rather than providing an additional first-touch advantage to an unrelated player.」(「핑드 패스 — 패스 수신자의 트랩 오차를 약간 줄여주던 효과를 제거했다. 이 변경으로 해당 PlayStyle은 무관한 선수에게 추가적인 퍼스트 터치 이점을 주는 대신 패스 전달력 자체를 향상시키는 데 주력하게 된다.」) — EA FC27 Gameplay Deep Dive. 독일어판 「Wir haben den Effekt entfernt, durch den die Ballannahme-Fehlerquote beim passempfangenden Profi leicht verringert wurde.」(「패스를 받는 선수의 볼 수신 오차율을 소폭 낮춰주던 효과를 제거했다.」) · 프랑스어판 「Suppression de l''effet qui réduisait légèrement l''erreur de contrôle pour le receveur de passe」(「패스 수신자의 컨트롤 오차를 소폭 줄여주던 효과 삭제」) · 포르투갈어판 「o efeito que reduzia levemente o erro de domínio em atletas que recebiam o passe」(「패스를 받는 선수의 트래핑 오차를 약간 줄여주던 효과」). 영·독·불·포르투갈 4개 언어권 EA 공식판에서 독립 확인.','⛔ 「패서를 좋게 만들면 리시버의 퍼스트 터치도 좋아진다」는 FC26까지만 성립한다. FC27 처방에서는 **리시버 본인의 볼컨트롤·침착·First Touch PlayStyle을 각자 따로 평가**해야 하고, 패서의 PlayStyle로 리시버의 결점을 가리는 설계(티키타카형 짧은 연계)는 폐기한다. 진화 선택에서도 리시버 측 원 스탯의 가치가 상대적으로 올라간다.','reports/research/2026-09-21-fc27-system-stats.md (워크플로 fc27-system-research, 8에이전트 다국어 수집 + 2표 반증 검증, 2026-09-21)','HIGH — EA 1차(피치노트) · 4개 언어권 공식판 독립 확인','2026-09-21','핑드 패스·티키타카의 수신 보정 제거');
INSERT INTO game_system_changes VALUES(23,'FC26','attributes','⭐ 퍼스트 터치 난이도는 볼컨트롤 단독 판정이 아니다 — **볼컨트롤·인터셉트·침착 3개 속성의 복합**이며, 그 위에 상황 변수 6종(선수 속도 대비 볼 속도·볼 높이·요구 이탈 각도·상대 압박·터치에 쓴 신체 부위·뻗는 정도)이 얹힌다. 또한 L2/LT 홀드가 이동 속도를 대가로 컨트롤을 크게 개선하며, 입력이 이를수록 컨트롤이 좋아진다.','원문 「Factors influencing the difficulty of a first touch include ball speed relative to the player''s speed, ball height, requested exit angle, opponent pressure, the part of the body used for the touch, the extent of stretching, and player attributes such as Ball Control, Interceptions, and Composure.」(「퍼스트 터치의 난이도에 영향을 주는 요인에는 선수 속도 대비 볼 속도, 볼 높이, 요구되는 이탈 각도, 상대의 압박, 터치에 사용된 신체 부위, 뻗는 정도, 그리고 볼컨트롤·인터셉트·침착 같은 선수 속성이 포함된다.」) · 「holding L2 || LT will greatly improve the players ability to control the ball at the trade-off of player''s move speed. Earlier timing of this input will result in increased control.」(「L2/LT를 누르고 있으면 선수의 이동 속도를 대가로 공을 다루는 능력이 크게 향상된다. 이 입력을 더 일찍 넣을수록 컨트롤이 더 좋아진다.」) — EA FC26 Gameplay Deep Dive. 포르투갈어판도 동일: 「qualidades de atleta como controle de bola, interceptações e frieza」(「볼컨트롤·인터셉트·침착 같은 선수 스탯」).','⑴ 「퍼스트 터치 = 볼컨트롤」 통념은 EA 1차 서술과 다르다 — 인터셉트·침착도 같은 식의 항이다. ⑵ 「압박 하 수신」은 별도 계수가 아니라 **같은 판정식의 한 항**이다. ⑶ 낮은 볼컨트롤의 트랩 열세는 **조작(L2/LT)으로 일부 메울 수 있다** — 스탯만으로 체감을 귀속하면 안 되고, 통제 실측을 설계할 때 이 입력을 고정하지 않으면 결과가 무효다.','reports/research/2026-09-21-fc27-system-stats.md (워크플로 fc27-system-research, 8에이전트 다국어 수집 + 2표 반증 검증, 2026-09-21)','HIGH — EA 1차(피치노트) 원문 인용','2026-09-21','퍼스트 터치 = 볼컨트롤·인터셉트·침착 복합');
INSERT INTO game_system_changes VALUES(24,'FC27','attributes','⭐ 신규 Off-Balance Dribbling의 입력 속성은 **Balance·Agility·Dribbling**이고 **볼컨트롤은 배제**됐다. 즉 「접촉·경합 중 볼 유지」 축과 「정적 수신(트랩)」 축이 서로 다른 스탯 묶음으로 갈라져 있다.','원문 「Driven by Balance, Agility and Dribbling Attributes」(「Balance·Agility·Dribbling 속성으로 구동되며」) — EA FC27 Gameplay Deep Dive. 독일어판은 판정 조건을 더 구체적으로 쓴다: 「Wenn ein Dribbelprofi mit den benötigten Werten von einem Zusammenprall, einem Rempler oder einem Schulterrempler getroffen wird, geht der Profi in eine Dribbling-im-Stolpern-Animation über.」(「필요한 수치를 갖춘 드리블 선수가 충돌·몸싸움·어깨싸움을 당하면, 그 선수는 ''비틀거리며 드리블'' 애니메이션으로 전환된다.」) — 「benötigten Werten」(필요한 수치)이라는 표현은 계단형 게이팅을 시사하나 EA가 컷 수치를 공개하지 않았다.','「압박 속에서 공을 지킨다」는 하나의 체감이 게임 내부에서는 **두 개의 판정식**으로 갈라진다 — 수신은 볼컨트롤·인터셉트·침착, 접촉 유지는 Balance·Agility·Dribbling. 처방에서 두 축을 섞지 말 것. ⚠️ gamereactor.fr 핸즈온 기사가 「볼컨트롤이 좋은 선수가 소유권을 유지한다」고 썼으나 EA 공식 프랑스어판과 충돌하므로 EA를 채택한다.','reports/research/2026-09-21-fc27-system-stats.md (워크플로 fc27-system-research, 8에이전트 다국어 수집 + 2표 반증 검증, 2026-09-21)','HIGH — EA 1차(피치노트) · 영·독·불 3개 언어권 대조','2026-09-21','오프밸런스 드리블 = 균형·민첩·드리블(볼컨 제외)');
INSERT INTO game_system_changes VALUES(25,'FC27','attributes','⛔⛔ 반응력(Reactions)은 EA 1차 자료에 **정의도 작용 서술도 없다**(부재 증거). FC25·FC26·FC27 게임플레이 딥다이브 전문과 EA Help 전체에서 기능 설명이 0건이고, FC26 퍼스트 터치 인자 목록에도 빠져 있다. FC27 문서에 등장하는 Reactions는 Pro 아키타입 마스터리 보상 표의 **항목명**일 뿐이다.','FC27 Gameplay Deep Dive 전수 키워드 스캔: Reactions 0회 · Ball Control 0회 · Composure 0회 · First Touch 0회. Closed Beta Feedback Update·Career Deep Dive·Ratings Deep Dive도 전부 0회. help.ea.com에 FC27 속성 설명 문서 자체가 없다(검색 21건 전량 확인). 널리 퍼진 통설 「반응력은 조작 중인 선수에게도 적용된다」(es.fifauteam.com)는 2/2 반증으로 기각 — 측정 근거 0건이고 영어 원문과 스페인어 번역판이 **동일 출처**라 다국어 교차검증에 해당하지 않으며 FIFA16 이후 재검증 없이 복제돼 왔다.','⑴ 「반응력 = 세컨볼·리바운드·루즈볼 경합」은 **D등급(통설, 1차 근거 없음)**이다 — 리포트·처방에서 등급을 밝히지 않고 쓰지 말 것. ⑵ 「AI 전용」도 「양쪽 적용」도 **둘 다 근거가 없다**. ⑶ 조작 주체(유저 vs AI)에 따라 달라진다고 EA가 명시한 유일한 항목은 **수비 리치 한 건뿐**이다(FC27, Competitive 한정). ⑷ 우리 「자율 판단 지수」가 반응력에 가중 .25를 주는 것은 여전히 **파생 휴리스틱**이며 EA 공식이 아님을 유지 표기한다. ⇒ 필요한 것은 프랙티스 아레나 A/B 실측(리바운드 볼 획득률·첫 터치 성공률)이다.','reports/research/2026-09-21-fc27-system-stats.md (워크플로 fc27-system-research, 8에이전트 다국어 수집 + 2표 반증 검증, 2026-09-21)','HIGH(부재 증거) — 1차 문서 전수 스캔으로 확인. ⚠️ 「없다」는 것이지 「작동하지 않는다」가 아니다','2026-09-21','반응력은 EA 1차 정의가 없다');
INSERT INTO game_system_changes VALUES(26,'FC27','attributes','침착(Composure)에 대해 EA 1차로 확인되는 기능은 **둘뿐**이다 — ⑴ 퍼스트 터치 난이도 계산의 입력 속성(FC26) ⑵ 페널티킥 Composure Circle의 수축 속도·퍼펙트 타이밍 창 크기(FC25). 그 외 서술은 1차 근거가 없다.','널리 퍼진 「침착 = 압박 인지 반경」 정의는 2/2 반증으로 기각됐다. 스페인어권 원문 「Este atributo determina a qué distancia el jugador con la pelota comienza a sentir la presión del oponente.」(「이 속성은 볼을 가진 선수가 상대의 압박을 느끼기 시작하는 거리를 결정한다.」 / es.fifauteam.com) · 독일어권 용어집 「Ruhe: Dieser Wert zeigt, ab Entfernung der Spieler durch einen Gegenspieler unter Druck gerät.」(「침착: 이 값은 선수가 상대 선수에 의해 어느 거리부터 압박을 받게 되는지를 보여준다.」 원문 오탈자 그대로 / onefootball.com) — 그러나 둘은 독립 관측이 아니라 **동일 계보의 복제**라 다국어 교차검증으로 카운트할 수 없다.','침착을 **''거리 파라미터''가 아니라 ''압박 하 액션 오차 계수(퍼스트 터치 포함)''로 기록**한다. 거리 해석은 채택하지 않는다. 슈팅 전용 스탯이라는 반대쪽 통념도 틀렸다 — EA 1차가 퍼스트 터치 입력으로 명시한다.','reports/research/2026-09-21-fc27-system-stats.md (워크플로 fc27-system-research, 8에이전트 다국어 수집 + 2표 반증 검증, 2026-09-21)','HIGH — EA 1차 2건 확인 + 통설 1건 2/2 반증','2026-09-21','침착의 확인된 기능은 두 가지뿐');
INSERT INTO game_system_changes VALUES(27,'FC27','meta','케미 기준선은 클럽 2/4/7 · 리그 3/5/8 · 국적 2/5/8 (각각 +1/+2/+3) — FC27에서도 그대로다','원문 「Club 2/4/7 · Nation 2/5/8 · League 3/5/8 players for +1/+2/+3」(각각 클럽 2·4·7명, 국적 2·5·8명, 리그 3·5·8명이 모이면 +1·+2·+3 케미) — timesaver.gg FC27 케미 해설(2026-09-14 런치 업데이트 반영)','우리 solver·화면의 CHEM 상수와 **일치 확인**. 바꿀 것 없음 — 다만 「확인했다」는 사실 자체가 값이다(종전엔 근거 없이 쓰고 있었다)','timesaver.gg FC27 chemistry explained · fifauteam FC26 chemistry','B — 커뮤니티 정리(EA 패치노트 인용 포함) · 1차 자료 아님','2026-09-25','케미 기준선(클럽·리그·국적) 유지');
INSERT INTO game_system_changes VALUES(28,'FC27','meta','⭐ 아이콘 국적 기여 +2 → **+1**, 히어로 리그 기여 +2 → **+1** (2026-09-14 런치 업데이트). Hall of FUT는 히어로 규칙을 따른다. 아이콘의 「모든 리그에 +1」은 유지','EA 문구 인용 「Heroes will also continue to receive full Chemistry when played in position, while their League contribution is being reduced from +2 to +1.」(히어로는 자리에 맞게 기용되면 계속 완전 케미를 받지만, 리그 기여는 +2에서 +1로 줄어든다)','⛔ 케미 보정값을 코드에 박으면 안 된다는 실증이다 — 박았다면 2026-09-14에 조용히 틀렸다. ⇒ sbc_solve.chem_total은 규칙 대신 fut.gg의 `player_card_items.chem_extra`를 읽는다(migration 044와 같은 방침)','timesaver.gg FC27 chemistry explained (EA 런치 업데이트 인용)','B — 데이터마이닝·패치노트 정리. ⚠️ 우리 보유분에 아이콘·히어로가 0장이라 **통제 실측을 못 했다**','2026-09-25','아이콘·히어로 케미 기여 +2 → +1');
INSERT INTO game_system_changes VALUES(29,'FC27','meta','아이콘·히어로는 자리에만 맞으면 **무조건 케미 3**이다(주변 구성과 무관)','원문 「Icons always have three chemistry points when playing in their preferred positions, regardless of the rest of the squad」(아이콘은 선호 포지션에서 뛰면 스쿼드의 나머지와 무관하게 항상 케미 3점을 가진다)','sbc_solve.chem_total에 반영. 아이콘 1장이 SBC 케미 조건을 크게 흔든다 — 구매 제안에서 우선 고려 대상','fifauteam FC26 chemistry · timesaver.gg FC27','B','2026-09-25','아이콘·히어로는 자리만 맞으면 케미 3');
INSERT INTO game_system_changes VALUES(30,'FC27','meta','⭐ 자리 안 맞는 선수는 **본인 케미 0**일 뿐 아니라 **남의 링크에도 기여하지 않는다**. 다만 제출 자체는 막히지 않고 팀 레이팅에도 영향이 없다','원문 「A player must be played in one of their listed positions to be eligible for chemistry at all. Out of position, they sit at 0」(케미를 받으려면 카드에 적힌 포지션 중 하나로 뛰어야 한다. 자리를 벗어나면 0이다) · 한국어 자료 「아웃 오브 포지션 = 0 케미, 단 팀 평점에는 영향 없음」','⑴ 배치가 최적화 문제라는 근거 — 이것 때문에 place()를 탐욕법에서 최대 매칭+국소탐색으로 바꿨다. ⑵ 화면이 「빨간 칸이어도 제출은 된다」고 단언할 근거','timesaver.gg FC27 · Vortex Gaming 한국어 정리','B — 영어·한국어 자료가 독립적으로 같은 말을 한다','2026-09-25','자리 안 맞는 선수는 케미 0 · 링크 기여도 없음');
INSERT INTO game_system_changes VALUES(31,'FC27','meta','⚠️ 감독은 국적 또는 리그가 같은 선발에게 **+1 케미**를 준다(선수당 1점 상한). SBC 스쿼드에도 적용된다','원문 「Your Manager contributes a flat +1」(감독은 일괄 +1을 준다) · SBC 적용 여부는 「managers do contribute toward chemistry in Ultimate Team, including in SBC squads」(감독은 SBC 스쿼드를 포함해 얼티밋팀에서 케미에 기여한다)','⛔ 우리는 **세지 않는다** — 어느 감독을 쓸지 사용자만 안다. ⇒ 우리 케미 값은 **하한**이고, 「케미 부족」 판정이 실제로는 감독으로 메워질 수 있다. 화면에 그 사실을 적었다','fifauteam FC26 chemistry · fifplay/thefuthub SBC 가이드','C — 출처가 서로 엇갈린다고 스스로 밝힌다(「FC 26 chemistry guides differ slightly on how much the manager contributes」(FC 26 케미스트리 가이드는 감독이 얼마나 기여하는지에 대해 조금씩 다르게 말한다)). ⛔ 통제 실측 필요','2026-09-25','감독 케미 +1(국적·리그 일치)');
INSERT INTO game_system_changes VALUES(32,'FC27','meta','팀 레이팅 = 평균 + (평균 초과분의 합 / 인원), **내림**. EA는 산식을 공개한 적이 없다','커뮤니티 역산 「SR = (SUM + CF) / N … rounded down」(합 + 보정계수를 인원으로 나눈 뒤 내림) · 「a computed 82.9 is an 82, not an 83」(82.9로 계산되면 83이 아니라 82다)','우리 team_rating()과 **일치 확인**. ⭐ 파생 전략: 보정계수가 평균 초과분만 보상하므로 **상위 1~2장을 높이고 나머지를 낮게** 채우는 편이 싸다(top-heavy). 지금 솔버는 이걸 노리지 않는다 — 보유분 판정이라 비용 축이 없기 때문이다','fifauteam FC26 squad rating guide · FUTBIN rating combinations','D — 커뮤니티 역산. 출처가 「EA가 공개한 적 없다」고 명시한다','2026-09-25','팀 레이팅 산식(EA 비공개 · 추정)');
INSERT INTO game_system_changes VALUES(33,'FC27','meta','SBC 요구 조건에는 **희귀도(Rare/Common/TOTW 등)** 축이 따로 있다 — Bronze/Silver/Gold 등급과 별개다','독일어 자료 「Eine Goldkarte mit Qualität „Selten" erfüllt eine solche Bedingung dann nicht」(품질이 「레어」인 골드 카드는 그런 조건을 충족하지 못한다) · Regista6 솔버가 지원하는 제약에 「Rarity constraints — Minimum players of specific rarity types」(특정 희귀도의 최소 인원)가 있다','⚠️ 우리 수집분 65개 조건 문장에는 **아직 안 나왔다**. ⛔ 그래서 패턴을 미리 발명하지 않는다 — sbc_solve는 못 읽은 문장을 「판정 불가」로 떨어뜨리므로 나오면 그때 드러난다. 이 행은 **나올 것을 알고 있다**는 기록이다','EA 포럼 독일어 · github.com/Regista6/EA-FC-Automated-SBC-Solving','B','2026-09-25','SBC 희귀도 조건은 등급과 별개');
INSERT INTO game_system_changes VALUES(34,'FC27','meta','커뮤니티 SBC 솔버의 정석은 **(선수×슬롯) 이진변수 정수계획법**(OR-Tools CP-SAT)이고, 비선형인 팀 레이팅 내림·케미 때문에 **담금질+정확해 재계산 하이브리드**를 쓰는 구현이 많다','Regista6/EA-FC-Automated-SBC-Solving(CP-SAT · 최소 비용 목적) · theblakelalonde/fc-sbc-solver(「for chemistry SBCs it runs simulated annealing then an exact re-solve … every squad is re-checked by independent rule code before placement」(케미스트리 SBC의 경우 시뮬레이티드 어닐링을 돌린 뒤 정확한 재풀이를 하며… 모든 스쿼드는 배치 전에 독립된 규칙 코드로 다시 검사된다) = 케미 SBC는 담금질 후 정확해로 재계산하고, 모든 스쿼드를 배치 전에 독립 규칙 코드로 재검증한다)','⭐ 우리와 같은 결론에 이미 도달해 있었다 — 「독립 규칙 코드로 재검증」은 2026-09-25에 우리가 저장 직전 게이트로 넣은 것과 같다. ⚠️ 차이: 우리는 **비용 목적이 없다**(시세 미공개) — 그래서 최소 비용 IP가 아니라 보유분 탐색이 맞다','github.com/Regista6/EA-FC-Automated-SBC-Solving · github.com/theblakelalonde/fc-sbc-solver · github.com/kosciukiewicz/sbc-solver','B — 공개 구현 원문','2026-09-25','SBC 솔버 정석 — 정수계획법 + 담금질');
INSERT INTO game_system_changes VALUES(35,'FC27','meta','SBC 제출은 **되돌릴 수 없고** 제출한 카드는 구단에서 영구 제거된다. 교체·예비 선수·감독은 조건 계산에 들어가지 않는다(선발 11명만)','EA 도움말 「substitutes, reserves, and managers do not count」(교체·예비·감독은 계산에 들어가지 않는다) · 독일어 「Sämtliche SBC-Einreichungen lassen sich nicht rückgängig machen」(모든 SBC 제출은 되돌릴 수 없다)','⚠️ 우리 원장에 **카드 소모 추적이 없다** — 제출한 11장이 어떤 카드였는지 EA가 주지 않아 다음 싱크까지 「보유」로 남는다. ⇒ 연속 SBC 해법이 이미 낸 카드를 다시 쓸 수 있다. 화면·보고에 이 한계를 적는다','help.ea.com Squad Building Challenges · EA 포럼 독일어','A — EA 1차 자료','2026-09-25','SBC 제출은 되돌릴 수 없고 선발 11명만 계산');
INSERT INTO game_system_changes VALUES(36,'FC27','meta','얼티밋팀 갤러리 태그 보너스 계산 규칙 — 태그마다 「해당 아이템 점수 합 × %」를 내림해 더한다 · 포지션 태그는 보조 포지션까지 센다 · 여자팀은 남자팀과 다른 클럽 · 같은 아이템은 세트에 한 장만 · 세트에 넣은 아이템은 판매·SBC 후에도 남는다 · 한 아이템을 여러 세트에 넣을 수 있다','인게임 「태그 용어집」 21칸 중 발견 12종의 조건·단계(원문 한국어 UI): 전력으로 공격 「공격 포지션(ST, RW, LW)의 선수가 필요합니다」 5-9 3% / 10-14 6% / 15+ 10% · 미드필드 컨트롤(CDM, CM, CAM, LM, RM) 동일 · 수비벽(CB, LB, RB) 동일 · 골키퍼만 3-5 3% / 6-9 6% / 10+ 15% · 중복! 「같은 선수 2명이 필요합니다」 2 10% / 3 15% / 4+ 20% · 최초 소유자 5-9 150% / 10-19 300% / 20+ 500% · 골드 1/2/4% · 같은 리그 1/2/8% · 같은 클럽·다른 클럽·다른 국가·같은 국가 1/2/4% (5-9/10-19/20+). 아스톤 빌라 세트(D) 기본 3,980 + 보너스 544 = 4,524 — 미드필드 12장 6% 192 + 수비 6장 3% 40 + 골드 15장 2% 79 + 다른 국가 15 2% 79 + 같은 리그 14 2% 77 + 같은 클럽 14 2% 77 = 544(1점 단위 일치). 태그를 누르면 해당 아이템만 하이라이트 — Cash(RB/RM)·Maatsen(LB/LM)·Ruggeri·Wan-Bissaka가 수비벽과 미드필드 양쪽, Kielland(빌라 여자팀 · WSL)는 같은 클럽·같은 리그에서 제외. 스타터 세트(S) 기본 2,690 + 보너스 4,113 = 최초 소유자 5장 150% 4,035 + 골드·다른 클럽·다른 국가 각 26. 브라이튼 세트에 처분한 Kirby가 남아 있고 빈칸 후보는 「조건에 맞는 아이템을 찾을 수 없습니다」. Groß(TOTW)가 브라이튼·프리미어 리그 양쪽에 있음. 스토리지 중복 맥긴은 두 번째 장이 들어가지 않음(사용자 확인).','core/gallery.py tag_bonus 정본 반영(내림·보조 포지션·(클럽,리그) 키·아이템 중복 제거 · POS_GROUP에서 CF·LWB·RWB 제거) · TAG_VERIFIED 12종 등급 A. 미발견 9종(브론즈·실버·다른 리그·TOTW·히어로·아이콘·개인기·약발·홀로그램)은 공개 표(timesaver) 등급 D 유지. ⚠️ 갤러리 진행 상태(세트에 이미 넣은 아이템)는 fut.gg가 주지 않고, 예전에 가졌던 아이템이 대거 들어가 있어(레알 마드리드 16장 vs 우리 원장 8장) 보유 카드만으로는 인게임 점수를 재현할 수 없다.','PS 리모트 캡처 36장 captures/gallery-2026-10-03 (사용자 · 2026-10-03)','A — 태그 단계·조건은 EA 인게임 UI 원문. C — 계산 규칙(내림·보조 포지션·여자팀 클럽)은 2세트 점수의 1점 단위 재현으로 확인한 통제 실측. 미발견 9종은 미확인(D).','2026-10-03','갤러리 태그 보너스 계산 규칙');
INSERT INTO game_system_changes VALUES(37,'FC27','meta','얼티밋팀 갤러리 태그 세부 규칙(커뮤니티 조사) — 「다른 ○○」는 값마다 최고 점수 1장에만 가산 · 「같은 ○○」는 가장 큰 무리(동률이면 점수 합 큰 쪽) · 「중복!」은 같은 선수 가장 큰 묶음 하나 · 가장 큰 태그 10개만 반영 · TOTW=rarity 3 · 미발견 9종 단계(브론즈 20/40/80 · 실버 15/30/60 · 다른 리그 1/2/4 · TOTW 3/6/10장 4/8/15 · 히어로 2/4/6장 8/12/20 · 아이콘 10/15/25 · 개인기·약발 3/5/10장 3/6/12 · 홀로그램 8/12/20)','fut.gg 세트 페이지 내장 EA 형식 태그 정의(capturedAt 2026-09-27 · 21종 rules·tiers — 인게임 확인 12종과 전부 일치) + fut.gg 계산기 최적 조합 16건(태그별 bonus=floor(pct×matchedScore) 전 건 일치 · top-10 컷 9건 1점 단위 일치 · 우리 tag_bonus로 15/16 재현, 불일치 1 = 히어로 세트 클럽 처리). 다른 매체(timesaver·Red Bull·Prima·futgenie 등)는 fut.gg 복제라 독립 출처 아님. 다국어 검색 현지 수치 0건.','core/gallery.py tag_bonus 반영 · 태그 정리표 미발견 9종 D→B. 인게임 스냅숏 재현: 아스톤 빌라·스쿼드 기초 0 · 스타터 +0.6% · 세리에 A −2.1% · 프리미어 리그 +4.0% · 라리가 +10.5%(원장 밖 카드 퍼스트 오너 가정). 미확인: Different League 5–9장 1%/2% · 히어로 클럽(114605) 「같은 클럽」 · 홀로그램(원장에 정보 없음).','reports/research/2026-10-03-fc27-gallery-community.md (웹 조사 · fut.gg·EA 피치노트·timesaver·Red Bull·futgenie·neuralboost)','B — fut.gg 데이터마이닝 정의 + 계산기 재현(인게임 아님). top-10 규칙은 B−(fut.gg 구현 · 인게임 칩 10개 정황).','2026-10-03','갤러리 태그 세부 규칙(커뮤니티 조사)');
INSERT INTO game_system_changes VALUES(38,'FC27','meta','얼티밋팀 팀 평점(스쿼드 레이팅) 계산식 — 평균을 넘는 선수는 넘는 만큼 한 번 더 센다: (합 + Σ평균 초과분)을 반올림 ÷ 인원수 → 내림. 인원수는 활성 스쿼드 18명(선발 11+교체 7, 리저브 제외) · SBC 11명. 다른 구현: 조정 평균을 소수 둘째 자리로 반올림 후 소수부 ≥0.96이면 +1, 버림','fifauteam FC27 Squad Rating Guide 「The exact calculation method is not publicly disclosed」(정확한 계산 방법은 공개되지 않았다) · 「SR = (SUM + CF) / 18」 · fut-squad-lab PR #59 「rating <= mean ? rating : 2 * rating - mean」(평균 이하면 그대로, 넘으면 2×평점−평균) · 같은 프로젝트도 「not confirmed it against EA''s live UI」(EA 실제 화면과 대조하지 못했다)고 명시. 구 FIFA 19는 교체 초과분을 ½로 셌다는 기록이 있으나 FC27 확인 없음.','얼티밋팀 「지금 내 팀」 팀 평점 ≈ 표시(활성 스쿼드 18명 · 저장 처방은 11명). 인게임 값과 대조 필요 — 아스톤 빌라 활성 스쿼드 계산값 81(2026-10-06).','https://fifauteam.com/fc-27-squad-rating-guide/ · https://github.com/benneknudsen/fut-squad-lab/pull/59 · https://github.com/benneknudsen/fut-squad-lab/issues/53','D — EA 미공개 · 커뮤니티 역산. 인원수(18명)는 가이드 1곳, 0.96 반올림 규칙은 오픈소스 1곳이며 둘 다 인게임 대조 기록 없음.','2026-10-06','팀 평점 계산식 — 평균 초과분을 한 번 더 센다');
INSERT INTO game_system_changes VALUES(39,'FC27','meta','홀로그래픽 아이템 — 특수 선수 아이템(TOTW 1부터)에만 있는 코스메틱 변형. 브론즈·실버·골드 기본 카드에는 없다. 특수 카드마다 홀로 버전이 별도 아이템으로 하나 있고 Regular 또는 Pristine(이름이 특수 서체) 중 하나다(둘 다는 아님). 능력치·PlayStyle 동일. 획득: ⑴ 팩 — 해당 특수 카드를 뽑을 때 확률로 홀로 버전이 나온다(확률 미공개 · 고정 목록 보장 팩·픽은 제외) ⑵ 이적시장(거래 가능 홀로) ⑶ 갤러리 레벨 보상(10 홀로 베이스 히어로 · 15 홀로 아이콘 · 20 88+ 홀로 히어로 · 25 92+ 홀로 아이콘 픽). 아이템 점수를 올리고 갤러리 「홀로그램」 태그(2–3장 8% · 4–5장 12%)를 연다.','timesaver 「Holographic versions apply to eligible special Player Items, not base Bronze, Silver and Gold items」(홀로 버전은 해당 특수 선수 아이템에 적용되며 브론즈·실버·골드 기본 아이템에는 없다) · 「Each eligible item is either Regular Holographic or Pristine Holographic — never both」(각 아이템은 일반 홀로 또는 프리스틴 홀로 중 하나이며 둘 다는 아니다) · Prima·Dexerto·TheGamer·Red Bull 동일 취지(서로 옮긴 글일 가능성 — 독립 교차검증 아님) · 갤러리 레벨 보상 단계는 games.gg·Prima 인용.','core/gallery.py 홀로그램 태그는 계속 계산 제외 — 원장에 홀로 여부가 없다(fut.gg 아이템 hyper-cosmetic 값으로 채울 수 있음). 홀로 아이템 점수 배율(×1.5)은 커뮤니티 역산 D.','https://timesaver.gg/blog/fc-27-holographic-items-explained-regular-pristine-how-to-get · https://primagames.com/gaming/how-to-get-holographic-autograph-cards-in-ea-fc-27-ultimate-team · https://www.dexerto.com/wikis/ea-fc-27/holographic-and-pristine-cards/ · https://games.gg/ea-sports-fc-27/guides/fc-27-how-to-get-holographic-cards/','D — 커뮤니티 매체(EA 1차 원문 미확인). 갤러리 레벨 보상 단계는 인게임 갤러리 레벨 화면으로 확인 가능.','2026-10-06','홀로그래픽 아이템 규칙');
INSERT INTO game_system_changes VALUES(40,'FC27','meta','팀 평점 공식(#38) 인게임 대조 1건 일치 — 아스톤 빌라 활성 스쿼드(선발 11 + 교체 7, 2026-10-06 싱크) 계산값 81 = 인게임 81. 단순 평균(선발 80.4)으로는 80이라 「평균 초과분을 한 번 더 센다」는 보정이 있어야 맞는다.','사용자 인게임 확인 「팀 평점은 게임내에서 81이야」(2026-10-06). 계산: site/evolutions.html squadRating — floor(round(합 + Σ평균 초과분) ÷ 18).','#38의 근거 D → 이 스쿼드 1건 C. ⚠️ 18명 vs 11명 구분은 이 건으로 갈리지 않았다(11명 기준도 81) — 교체 평점이 크게 다른 스쿼드에서 다시 대조할 것.','사용자 인게임 확인(PS) · game_system_changes #38','C — 통제 실측 1건(표본 작음 · 인원수 규칙 미판별)','2026-10-06','팀 평점 공식 인게임 대조 1건 일치');
INSERT INTO game_system_changes VALUES(41,'FC27','evolution','진화 PlayStyle 보상의 「(^3)」 표기 = **보유 PlayStyle 개수 상한 3**. 이미 PlayStyle이 3개인 카드는 새 PlayStyle을 주는 가지를 받을 수 없다(갈림길에서 선택 불가). 이미 보유한 PlayStyle을 주는 가지는 고를 수 있다(PS 변화 없이 스탯만 오른다).','사용자 인게임 확인 2026-10-06 「이미 플레이스타일이 3개라 1 대1 클로즈다운 플레이스타일을 받을 수 없었어」 — 스즈키(PS Deflector·Cross Claimer·Pinged Pass) · Goal Guardian(2538) 2단계: 1번 가지 1v1 Close Down (^3) 선택 불가 → 2번 가지 Deflector (^3)(이미 보유) 선택. fut.gg 카탈로그 upgrades의 play_style maxValue=3이 이 상한이다(요구 조건 「Max PS 7」과는 별개 축).','진화 걸어보기·추천에서 PS 3개 보유 카드는 새 PS 가지를 「받을 수 없음」으로 처리해야 한다. 「PS 상한」은 진화마다 maxValue로 다를 수 있다 — 값은 카탈로그에서 읽는다.','사용자 인게임 확인(PS) · fc_evolutions evo_id 2538 levels','C — 인게임 실측 1건(카드 1장 · 진화 1종)','2026-10-06','진화 PS 보상 (^3) = 보유 PS 상한 3');
INSERT INTO game_system_changes VALUES(42,'FC27','meta','팀 평점 공식(#38) 인게임 대조 2건째 일치 — 스즈키 76→80 진화 후 아스톤 빌라 활성 스쿼드 계산값 81 = 인게임 81(선발 평균 80.73 · 18명 평균 80.5 → 단순 평균 내림이면 80이라 보정항이 또 필요했다).','사용자 인게임 확인 「팀 평점 81 그대로야」(2026-10-06, Goal Guardian 완료 직후). 선발 OVR [80,81,82,81,79,82,84,83,77,80,79] · 교체 7 [80,81,76,80,80,84,80].','#38 근거 C 2건. ⚠️ 이번에도 11명·18명 기준이 둘 다 81이라 인원수 규칙은 여전히 미판별 — 교체 평점이 선발보다 크게 낮거나 높은 스쿼드에서 대조할 것.','사용자 인게임 확인(PS) · game_system_changes #38 · #40','C — 통제 실측 2건(같은 스쿼드 · 인원수 규칙 미판별)','2026-10-06','팀 평점 공식 인게임 대조 2건째 일치');
INSERT INTO game_system_changes VALUES(43,'FC27','attribute','민첩성·균형·반응력·침착 커뮤니티 체감 재수집(출시 12일차 · docs/22 §2.1 「2~4주 후 재수집」 이행) — **새 1차(A)·데이터마이닝(B)·통제 실측(C) 0건**. 수집된 것은 통설(D)뿐: ⑴ Off-Balance Dribbling 발동 「민첩·균형·드리블 85 이상」(코인 판매 사이트 1곳 · 출시 전 2026-09-02 작성 · 단독) ⑵ 베타 체험 「문턱이 아니라 스탯이 높을수록 발동 확률이 오른다」(NealGuides) ⑶ 균형 「80 이상부터는 더 높아도 체감이 크지 않다」(FC26 디시 커서수비 글 · 버전 이월 주의) ⑷ 민첩 「방향 전환·조작이 가벼워진다」(다국어 공통 서술). 반응력·침착 서술은 전부 §2.1 기각 통설(압박 인지 거리 · 세컨볼 경합)의 복제였다.','Off-Balance 입력 3속성(Balance·Agility·Dribbling)은 EA 원문 재확인 「Driven by Balance, Agility and Dribbling Attributes, this allows certain players to continue dribbling even when they are knocked off balance.」(「균형·민첩·드리블 속성이 작동시키며, 균형을 잃은 상태에서도 특정 선수가 드리블을 이어가게 한다.」 / A, FC27). 수치 문턱은 EA 미공개. fcutcoins 「85 or higher in these three core stats: Agility, Balance, Dribbling」(「민첩·균형·드리블 세 핵심 스탯이 85 이상」 / D) — 같은 글이 「early hands-on gameplay and pre-beta impressions」(「초기 체험과 베타 전 인상」)이라 밝혀 통제 실측 아님. 독·스·일·한 매체는 FUTeam·EA 원문 번역 복제(독립 교차검증 아님). 일본어 검색은 체감 서술 0건. Reddit·futbin 접근 차단(우회 안 함).','얼티밋팀 처방: 드리블러 평가에서 민첩·균형은 Off-Balance 입력이라 근거 A로 쓸 수 있으나 「85 문턱」은 D — 문턱 판정에 쓰지 않고 「높을수록 유리」로만 쓴다. 반응력·침착은 여전히 §2.1 결론 유지(반응력 작용 1차 근거 없음 · 침착은 퍼스트 터치·PK 원 두 가지만).','웹 조사 2026-10-07 — ea.com FC27 Gameplay Deep Dive · fcutcoins.com off-balance guide · nealguides.com · hiddenribbon.com · gall.dcinside.com fifaseries 65320(FC26) · note.com/new_gate_green · fifauteam.com fc-27-attributes · vandal.elespanol.com','D — 커뮤니티 통설(통제 실측·데이터마이닝 0건). Off-Balance 입력 속성 자체만 A.','2026-10-07','민첩·균형·반응력·침착 체감 재수집 — 통설뿐');
INSERT INTO game_system_changes VALUES(44,'FC27','engine','⭐ 타이틀 업데이트 v1.0.1에서 **Authentic 프리셋 전용**으로 조키·스프린트 조키 기본 슬라이더 값이 중간 폭 상향됐다 — **Competitive에는 영향 없다**. The Grounds 11v11은 피로가 장기 스태미너에 주는 영향이 커졌다. 이후 **v1.0.2·v1.0.3·v1.0.4에는 게임플레이 변경이 0건**이다(1.0.3·1.0.4는 「게임플레이 밸런스·튜닝 변경 없음」을 본문에 명시, 1.0.2는 UT 버그 1건뿐).','「In Authentic Gameplay only (available in Career Mode and Kick Off) Jockey and Sprint Jockey Speed default slider values have moderately been increased. This change does not impact Competitive Gameplay.」(오센틱 게임플레이에서만 커리어 모드와 킥오프에서 이용 가능 재키와 스프린트 재키 속도의 기본 슬라이더 값이 적당히 상향되었다. 이 변경은 경쟁 게임플레이에 영향을 주지 않는다.)(Authentic 게임플레이에서만(커리어 모드·킥오프에서 사용 가능) 조키 및 스프린트 조키 속도 기본 슬라이더 값이 중간 정도로 상향됐다. 이 변경은 Competitive 게임플레이에 영향을 주지 않는다.) · 「In The Grounds 11v11 matches, increased the impact of fatigue on long-term player stamina.」(The Grounds 11v11 경기에서 피로가 선수의 장기 스태미너에 주는 영향을 증가시켰다.) · v1.0.3·v1.0.4 「There are no gameplay balance and tuning changes in this update.」(이 업데이트에는 게임플레이 밸런스·튜닝 변경이 없다.)','**C등급(통제 실측)을 할 때 프리셋을 반드시 명기해야 한다.** 우리가 전술 재현을 확인하는 자리는 커리어·킥오프(Authentic)인데, 바로 그쪽만 조키가 빨라졌다 — 같은 선수·같은 전술이라도 v1.0.0 Authentic에서 잰 수비 체감과 v1.0.1 이후 수치가 다르다. 기존 행 #15(수동 수비 강화는 Competitive 전용)의 전제가 **절반 깨졌다**: 수동 수비 보상은 여전히 Competitive 전용이지만, **조키 속도만은 Authentic에도 들어왔다**. ⇒ 앞으로 `match_game_setups`·실측 메모에 프리셋(Competitive/Authentic)과 타이틀 버전을 같이 적는다.','https://forums.ea.com/blog/ea-sports-fc-game-info-hub-en/fc-27-v1-0-1-small-bug-fix-update/13734805 (v1.0.1) · https://forums.ea.com/blog/ea-sports-fc-game-info-hub-en/fc-27-v1-0-2---small-bug-fix-update/13752885 (v1.0.2) · https://forums.ea.com/blog/ea-sports-fc-game-info-hub-en/fc-27-v1-0-3---small-bug-fix-update/13763421 (v1.0.3 · 2026-10-02) · https://forums.ea.com/blog/ea-sports-fc-game-info-hub-en/ea-sports-fc%E2%84%A2-27--title-update-v1-0-4/13777445 (v1.0.4 · 2026-10-07)','A (EA 1차 · 원문 직접 확인 2026-10-08). ⚠️ EA 포럼 Game Info Hub 글은 영어판만 존재해 다국어 대조가 불가능하다(불변규칙 10 예외 사유).','2026-10-08','TU 1.0.1 Authentic 조키 상향 · 이후 변경 0');
INSERT INTO game_system_changes VALUES(45,'FC27','positioning','⭐⭐ EA가 **풀백이 너무 일찍 내려와 수비 라인을 깨는 현상**을 출시 후 최다 피드백으로 공식 인정했다. 원인 조사 중이며 **아직 수정하지 않았다** — 커뮤니티의 「초반에 게임을 바꾸지 말라」 요구를 받아들여 조사를 끝낸 뒤에나 조정한다고 밝혔다.','en 「One of the largest quantities of feedback we''ve received has been around fullbacks dropping too early and breaking the defensive line.」(우리가 받은 피드백 중 가장 많은 양을 차지한 것 하나가 풀백이 너무 일찍 내려와 수비 라인을 깨는 문제에 관한 것이었다.) · de 공식판 「Wir hören im Feedback der Community sehr oft, dass die Außenverteidigung zu früh absinkt und die Defensivlinie auflöst.」(커뮤니티 피드백에서 측면 수비가 너무 일찍 내려앉아 수비 라인을 해체한다는 말을 아주 자주 듣는다.)','**에메리 재현의 핵심 전제가 흔들린다.** 우리 처방은 높은 수비 라인 + 풀백의 전진 유지를 전제로 역할·전술 슬라이더를 깔아 왔는데, 엔진이 풀백을 조기 하강시키면 그 라인이 실제로는 유지되지 않는다 — `prescriptions`의 풀백 역할·수비 라인 높이 항목이 **의도대로 재현되지 않고 있을 가능성**이 크다. ⚠️ 다만 EA가 **고칠 수도 있다고 밝힌 상태**라, 지금 체감에 맞춰 처방을 영구 변경하면 수정 패치 후 두 번 틀린다. ⇒ 처방은 그대로 두고, 인게임 관측(`reports/ingame/`)에 **「풀백 조기 하강 여부」를 고정 관측 항목으로 추가**해 수정 패치 전후를 비교할 수 있게 둔다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-gameplay-developer-launch-update (2026-09-30)','A (EA 1차 · 영어 원문 + 독일어 공식판 대조 2026-10-08). ⚠️ 교차검증 아님에 주의 — 같은 글의 EA 자체 번역이다(불변규칙 12). ⚠️ pt-br 공식판은 같은 문장을 「laterais avançando muito cedo」(풀백이 너무 일찍 **전진**)로 옮겨 en 「dropping」·de 「absinkt」(내려간다)와 **뜻이 반대다** — 로컬라이즈 오역으로 보고 en/de를 채택했다.','2026-10-08','풀백 조기 하강 공식 인정(미수정)');
INSERT INTO game_system_changes VALUES(46,'FC27','attributes','⭐ EA가 **수비 속성이 낮은 선수의 인터셉트가 과도하게 효과적일 수 있다**고 공식 인정했다 — 「최고 수비수에게나 기대할 법한 인터셉트」를 낮은 수비 스탯 아이템이 해내고 있다는 것. 다만 **수동 수비 보상이라는 설계 목표 자체는 달성됐다고 보고 유지한다**고 밝혔다(관측만, 미수정).','en 「Our design goals are to reward the manual defender for getting into passing lanes, and we feel we''re achieving that.」(우리의 설계 목표는 패스 길목에 들어가는 수동 수비자에게 보상하는 것이고, 우리는 그것을 달성하고 있다고 본다.) · en 「That said, players using items with lower defensive attributes may be too effective at making the types [of interceptions typically expected only of the best defenders].」(그렇지만 수비 속성이 낮은 아이템을 쓰는 플레이어가 보통 최고 수비수에게나 기대되는 종류의 인터셉트를 하는 데 지나치게 효과적일 수 있다.) · de 공식판 「Aber es kann vorkommen, dass Profis mit niedrigeren Defensivwerten zu effektiv sind. Solche Profis können Bälle abfangen, die eigentlich nur die besten Abwehrprofis abfangen sollten.」(하지만 수비 수치가 낮은 선수가 지나치게 효과적인 경우가 생길 수 있다. 그런 선수가 원래는 최고의 수비 선수만 끊어야 할 공을 끊어낼 수 있다.)','**수비 스탯 투자의 가성비 판단이 바뀐다 — 단, 한시적으로만.** 지금은 인터셉트 축에서 수비 스탯 문턱이 실질적으로 낮으므로, 중원·수비에 「인터셉트를 위해 수비 스탯을 더 산다」는 처방·진화 선택의 근거가 약하다 (같은 코스트면 다른 축이 낫다). ⚠️ EA가 명시적으로 **계속 모니터링한다**고 했으므로 이것은 **버그성 과효율일 가능성이 있는 상태**다 — `fut_evolution_log`·`prescriptions`에 이 사실을 근거로 쓸 때 「2026-10-08 기준 v1.0.4, EA 수정 예고 없음」을 함께 적는다. 수정되면 되돌려야 한다. ⭐ 반대로 **수동 수비 보상 설계는 유지된다**고 EA가 못박았으므로, 패스 길목 차단을 전제로 한 압박 처방(시메오네·에메리 중원 압박)은 그대로 유효하다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-gameplay-developer-launch-update (2026-09-30)','A (EA 1차 · 영어 원문 + 독일어 공식판 대조 2026-10-08). ⚠️ 교차검증 아님에 주의 — 같은 글의 EA 자체 번역이다(불변규칙 12). ⚠️ pt-br 공식판은 같은 문장을 「laterais avançando muito cedo」(풀백이 너무 일찍 **전진**)로 옮겨 en 「dropping」·de 「absinkt」(내려간다)와 **뜻이 반대다** — 로컬라이즈 오역으로 보고 en/de를 채택했다.','2026-10-08','낮은 수비 스탯 인터셉트 과효 인정(유지)');
INSERT INTO game_system_changes VALUES(47,'FC27','meta','출시 초기 밸런스 정책이 **실행으로 확인됐다**(기존 #18은 예고였다) — v1.0.1~v1.0.4 어디에도 코어 게임플레이 밸런스 변경이 없다. EA는 ⑴ 킥오프 직후 득점 증가를 데이터에서 관측 중 ⑵ 니어포스트 로우드리븐 슛이 강하다는 피드백은 받았으나 **「슛과 골키퍼의 현재 밸런스에 상당히 만족한다」**고 밝힘 ⑶ 현재 작업 중인 것은 **반칙 판정**뿐(특정 경합에서 심판이 올바른 결과를 주지 않는 문제)이라고 밝혔다.','en 「While we aren''t changing anything that would impact core gameplay, we are looking into several issues related to fouls.」(코어 게임플레이에 영향을 주는 것은 아무것도 바꾸지 않고 있지만, 반칙과 관련된 몇 가지 문제는 들여다보고 있다.) · en 「we''re pretty happy with the current balance between shooting and goalkeeping」(우리는 슈팅과 골키핑 사이의 현재 밸런스에 상당히 만족하고 있다) · en 「a presence on this list does not mean we will be making changes」(이 목록에 올라 있다는 것이 우리가 변경을 하리라는 뜻은 아니다)','**처방의 재검토 주기를 짧게 잡을 이유가 없다.** 2026-10-08 기준 v1.0.0의 게임플레이 튜닝이 사실상 그대로 살아 있다(Authentic 조키 1건 예외 — 같은 회차 engine 행 참조). ⇒ 지금 쌓는 인게임 실측은 **한 버전의 일관된 표본**으로 묶어도 된다 — docs/22 §2.1이 예고한 「출시 2~4주 후 C등급 통제 실측」에 지금이 적기다. ⚠️ 반대로 **반칙 판정은 곧 바뀐다** — 태클·경합 관련 실측(적극성 스탯의 반칙 리스크 축)은 지금 재면 수정 후 무효가 될 수 있으니 뒤로 미룬다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-gameplay-developer-launch-update (2026-09-30) · https://forums.ea.com/blog/ea-sports-fc-game-info-hub-en/fc-27-v1-0-1-small-bug-fix-update/13734805 (v1.0.1) · https://forums.ea.com/blog/ea-sports-fc-game-info-hub-en/fc-27-v1-0-3---small-bug-fix-update/13763421 (v1.0.3 · 2026-10-02) · https://forums.ea.com/blog/ea-sports-fc-game-info-hub-en/ea-sports-fc%E2%84%A2-27--title-update-v1-0-4/13777445 (v1.0.4 · 2026-10-07)','A (EA 1차 · 영어 원문 + 독일어 공식판 대조 2026-10-08). ⚠️ 교차검증 아님에 주의 — 같은 글의 EA 자체 번역이다(불변규칙 12). ⚠️ pt-br 공식판은 같은 문장을 「laterais avançando muito cedo」(풀백이 너무 일찍 **전진**)로 옮겨 en 「dropping」·de 「absinkt」(내려간다)와 **뜻이 반대다** — 로컬라이즈 오역으로 보고 en/de를 채택했다.','2026-10-08','초기 밸런스 동결이 실행으로 확인');
INSERT INTO game_system_changes VALUES(48,'FC27','meta','캠페인 업그레이드 페이싱 완화가 **런치 업데이트 예고(09-14) → FUT 개발팀 런치 업데이트(10-01) 재확인**으로 닫혔다 — 캠페인 간 속성 상승폭을 줄이고, 캠페인 스쿼드를 **작게·OVR 분포를 좁게** 간다. 목표는 「캠페인 스쿼드의 어느 아이템이든 선발 11명에 들 수 있게」. 연간 캠페인 주차도 약 5주 줄고 그 자리를 신규 스페셜 아이템 없는 Series가 채운다.','런치 업데이트 「We''re establishing a more gradual upgrade pacing across the year by reducing the maximum number of PlayStyles+ from five to three and reducing the attribute increases between Campaigns.」(우리는 PlayStyle+ 최대 개수를 5개에서 3개로 줄이고 캠페인 간 속성 상승폭을 축소함으로써 연중 업그레이드 속도를 더 완만하게 만들고 있다.) · FUT 개발팀 런치 업데이트 「we''re taking a more focused approach with smaller squads and a tighter OVR spread than in previous years」(우리는 예년보다 더 작은 스쿼드와 더 좁은 OVR 분포로 더 집중된 접근을 취하고 있다) · 「any Campaign squad item can earn a place in your starting XI」(캠페인 스쿼드의 어떤 아이템이든 당신의 선발 11명에 들 자격을 얻을 수 있다)','**처방의 유효기간이 길어진다.** FC26까지는 캠페인 아이템이 속성을 크게 밀어올려 「지금 좋은 카드」가 달마다 갈렸지만, FC27은 상승폭이 작아 한 번 맞춘 `prescriptions`를 시즌 내내 유지할 수 있다. ⭐ 더 중요한 반대 방향: **「캠페인 나오면 메워지겠지」로 미뤄둔 포지션은 캠페인이 메워주지 않는다** — SBC·진화·이적시장으로 직접 채워야 한다. 다음 /club-sync에서 결손 포지션을 캠페인 대기로 두지 말 것.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-launch-update (2026-09-14) · https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-fut-developer-launch-update (2026-10-01)','A (EA 1차 · 원문 직접 확인 2026-10-08). ⚠️ 두 글 모두 de/pt-br 로케일에서 영어 본문만 제공돼 다국어 대조가 불가능하다(불변규칙 10 예외 사유).','2026-10-08','캠페인 업그레이드 폭 완화');
INSERT INTO game_system_changes VALUES(49,'FC27','evolution','⭐ 진화(Evolutions) 규칙 변경 — 출시 **빈도를 낮추고** 의도된 시점에만 배포한다. 대신 **포지션·속성 요건이 구체화된 맞춤 성장 경로**로 바뀌어, 선수 고유의 강점을 보존하는 방향으로만 성장시킨다(런치 업데이트 09-14). FUT 개발팀이 10-01에 **「진화 튜닝에 의미 있는 변경을 가했다」**고 재확인했다. 저평점 선수용 Training Camp 진화는 확대.','런치 업데이트 「you can still expect to see impactful Evolutions throughout the year, just at a lower frequency and released at more intentional moments」(연중 영향력 있는 진화는 여전히 기대할 수 있지만, 빈도는 더 낮아지고 더 의도된 시점에 배포된다.) · 「Evolutions will also feature more tailored progression paths, with specific positional and Attribute requirements designed to preserve a player''s unique identity and on-pitch strengths as they grow.」(진화는 또한 더 맞춤화된 성장 경로를 갖게 되며, 선수가 성장하는 동안에도 고유한 정체성과 경기장에서의 강점을 보존하도록 설계된 구체적인 포지션·속성 요건이 붙는다.) · FUT 개발팀 런치 업데이트 「made meaningful changes to the tuning of Evolutions」(진화의 튜닝에 의미 있는 변경을 가했다)','**진화 선택 판단의 축이 바뀐다.** 빈도가 낮아져 진화 슬롯 한 칸의 기회비용이 커졌고, 요건이 포지션·속성으로 구체화돼 **요건에 걸리는 카드를 미리 확보해 두는 것**이 이득이 된다. `fut_evolution_log`에 후보를 남길 때 「왜 이 카드인가」를 포지션·속성 요건 기준으로 적는다. 진화가 고유 강점 보존 방향이라면, 우리 처방이 요구하는 역할별 속성(에메리식 역할 등)과 진화 요건이 겹치는 카드를 고르는 것이 가장 정확한 선택이다. 기존 행 #41(PlayStyle 보상의 (^3) = 보유 상한 3)과 같은 방향 — 진화로 메울 수 있는 폭 자체가 좁아졌다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-launch-update (2026-09-14) · https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-fut-developer-launch-update (2026-10-01)','A (EA 1차 · 원문 직접 확인 2026-10-08). ⚠️ 두 글 모두 de/pt-br 로케일에서 영어 본문만 제공돼 다국어 대조가 불가능하다(불변규칙 10 예외 사유).','2026-10-08','진화 출시 빈도 축소 · 맞춤 성장 경로');
INSERT INTO game_system_changes VALUES(50,'FC27','playstyles','⭐ EA 게임플레이 총괄 PD(Sam Rivera)가 밝힌 FC27의 **PlayStyle 효과 설계 목표 = 약 5~10% 보너스**. 「80 선수가 Finesse Shot을 달아도 99 선수보다 나아지지 않는다」 — 원 스탯이 지배하고 PlayStyle은 보정이라는 설계 의도를 수치로 처음 밝혔다. ⚠️ 측정값이 아니라 **설계 목표치**이고, 5~10%가 무엇의 5~10%인지(성공률·오차·속도)는 정의되지 않았다.','en 「Our goal for EA FC 27 is for a PlayStyle to give you a bonus of around 5 to 10 per cent.」(FC27에서 우리의 목표는 PlayStyle 하나가 약 5~10% 정도의 보너스를 주는 것이다.) · 「An 80-rated striker with Finesse Shot will never be better than a 99-rated striker.」(Finesse Shot을 가진 80 스트라이커가 99 스트라이커보다 나아지는 일은 절대 없다.) — Red Bull이 게임스컴 2026(쾰른)에서 들은 발언으로 소개(「told us」(우리에게 말했다)). pt-br 각색판 「Nosso objetivo para o EA FC 27 é que um Estilo de Jogo te dê um bônus de cerca de 5 a 10 por cento.」(FC27에서 우리의 목표는 플레이스타일이 약 5~10%의 보너스를 주는 것이다.) — 같은 기사의 각색 번역이라 교차검증 아님(불변규칙 12).','**과녁 1(First Touch가 볼컨트롤을 얼마나 덮는가)의 사전 기대값이 생겼다** — 설계 의도대로라면 First Touch 보정은 「작다」 쪽(H0)에 가깝다. 진화 선택에서 「PlayStyle 하나 vs 원 스탯 +N」을 고를 때 FC26식 PlayStyle 우선 판단을 낮춘다(docs/22 §6.1·§6.2 판정 규약에 반영 검토 — 사용자 판단). ⚠️ 설계 목표와 실제 효과는 다를 수 있다 ⇒ 2026-10-08 실측 프로토콜 P1의 판정(5%p 미만 = H0)으로 확인한 뒤에만 처방 근거로 쓴다.','https://www.redbull.com/int-en/ea-fc-27-guide-tips (2026-10-02 · Christian Knoth) · pt-br 각색 https://www.redbull.com/br-pt/ea-fc-27-guide-tips (2026-10-06)','A−(EA 개발자 직접 발언이지만 **EA 공식 게시물이 아니라 제3자 매체 인터뷰 인용** · 설계 목표치이며 측정값 아님). 패치 감시(EA 발행물만)의 수집 경로 밖이라 시스템 재조사가 적재. 2026-10-08 en 원문 직접 확인.','2026-10-08','PlayStyle 효과 설계 목표 약 5~10%');
INSERT INTO game_system_changes VALUES(51,'FC27','attributes','Off-Balance Dribbling 「발동 문턱」 통설의 **출처 계보와 상충**을 확인했다 — 숫자가 세 가지 버전으로 돈다: ⑴ 민첩·균형·드리블 **각각 85 이상**(fcutcoins · #43) ⑵ 세 속성 **합산(combined) 85 이상**(gamereactor.es 출시 전 시연 기사 07-31 · 합산 정의 없음) ⑶ 리크 계정 @FutPoliceLeaks 발 「테스트 중 85+」(검색 스니펫만 · 원문 402 차단) 및 같은 계정 발로 전해지는 「세 속성 평균 ≥75」(일본어 검색 요약 · 미확인). 셋 다 **출시 전** 자료이고 측정 설계가 없다. EA는 숫자를 공개하지 않았다(A).','es 「solo estará disponible para futbolistas con una puntuación combinada de 85 o más en regate, equilibrio y agilidad」(드리블·균형·민첩 합산 점수가 85 이상인 선수만 쓸 수 있다 / gamereactor.es 2026-07-31) · en 「During testing the requirements … were 85+ agility, balance & dribbling」(테스트 중 요구치는 민첩·균형·드리블 85 이상이었다 / @FutPoliceLeaks · 검색 스니펫, 원문 미열람) · en 「After tons of trial-and-error testing online」(온라인에서 수많은 시행착오 테스트를 거친 끝에 / fcutcoins 2026-09-02 · 표본·조건 서술 없음). fr·ja 매체의 「85」는 전부 fcutcoins 복제(독립 아님).','#43의 「85 문턱은 D — 문턱 판정에 쓰지 않는다」를 **강화**한다: D끼리도 숫자가 상충하므로(각각 85 / 합산 85 / 평균 75) 어느 값도 진화·영입의 컷으로 쓰지 않는다. 드리블러 평가는 「민첩·균형·드리블이 높을수록 유리」(A의 입력 속성)까지만 쓴다. 과녁 5는 **통제 실측 외에 닫을 길이 없다** — 실측 프로토콜 후보(2026-10-08 설계서 「다루지 않는 것」 표).','https://www.gamereactor.es/ea-sports-fc-27-avance-que-cambios-podemos-esperar-en-el-modo-carrera-y-en-la-gameplay-1757693/ · https://x.com/FutPoliceLeaks/status/2093251532766548129 (402 차단 · 스니펫) · https://www.fcutcoins.com/blog/fc-27-off-balance-dribbling-guide-how-to-use-best-players','D — 통설·리크(출시 전 · 통제 실측·데이터마이닝 0건). 2표 반증: 독립 출처 3곳이 서로 다른 수치를 대 **어느 수치도 생존하지 못함** — 이 행은 「문턱 값」이 아니라 「문턱 통설이 상충한다」는 사실을 적재한다. 입력 속성 3종 자체만 A(EA 딥다이브).','2026-10-08','오프밸런스 드리블 발동 문턱 통설 — 출처 상충');
INSERT INTO game_system_changes VALUES(52,'FC27','attributes','⭐ 로우 드리븐 슛의 **슛 속도 보너스가 제거**됐고, 슛 속도는 이제 **핵심 슈팅 속성과 입력 파워만으로** 정해진다. Low Driven PlayStyle(+)은 정확도 보너스만 남는다. 같은 패치에서 Finesse Shot도 회전·애니메이션 속도·각도 효과가 선수 속성에 따라 정해지도록 바뀌었다(#13과 같은 축).','EA 원문: 「Removed the shot speed boost previously applied to low-driven shots」(로우 드리븐 슛에 적용되던 슛 속도 보너스를 제거했다) · 「Shot velocity now scales purely based on core shooting Attributes and input power, for more consistent and attribute-driven results」(이제 슛 속도는 핵심 슈팅 속성과 입력 파워만으로 정해져, 더 일관되고 속성에 따른 결과가 나온다) · 「The Playstyle and PlayStyle+ still add an accuracy boost」(PlayStyle과 PlayStyle+는 여전히 정확도 보너스를 준다).','진화·카드 비교에서 **슈팅 속성(특히 슈팅력) 상승이 로우 드리븐 마무리의 슛 속도로 바로 이어진다**고 읽을 수 있다(A). ⚠️ 「core shooting Attributes」(핵심 슈팅 능력치)가 어느 속성인지(결정력·슈팅력·중거리 중 무엇이 얼마나)는 EA가 밝히지 않았다 — 속성별 비중은 미확인. 결정력=박스 안 발슛 정확도(docs/22 표)는 1차 근거가 없는 통설(D)이다. 2026-10-10 만잠비 Future Stars Academy I 갈래 비교에서 확인.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive','A — EA 1차(피치노트 게임플레이 딥다이브) 원문 직접 확인 2026-10-10','2026-10-10','로우 드리븐 슛 속도 보너스 제거');
INSERT INTO game_system_changes VALUES(53,'FC26','attributes','⭐ 힘·공격성의 확인된 작용 = **볼 지키기(쉴딩)·몸싸움**. ⑴ 힘·공격성이 높을수록 쉴딩이 낫다 ⑵ 힘 차이가 큰 어깨싸움에서 힘이 낮은 쪽이 더 자주 비틀거린다 ⑶ 공중볼 박스아웃 효과는 두 선수의 힘 차이로 정해진다 ⑷ 쉴드 트래핑에서 힘에 따른 차이를 키웠다.','EA 원문: 「players with higher Strength and Aggression Attributes can generally be better at shielding the ball」(힘·공격성 능력치가 높은 선수는 대체로 공을 더 잘 지킨다) · 「Shoulder challenges between players with a large Strength Attribute difference will more often result in the player with the lower Strength Attribute stumbling」(힘 차이가 큰 선수 간 어깨싸움은 힘이 낮은 쪽이 더 자주 비틀거리는 결과가 된다) — TU 1.4.0. 「The effectiveness of the Box Out is based on the Strength difference between the two players」(박스아웃 효과는 두 선수의 힘 차이로 정해진다) · 「Increased Strength-based differentiation when Shield trapping」(쉴드 트래핑 시 힘에 따른 차이를 키웠다) — Gameplay Deep Dive.','공격성이 EA 1차로 작용이 서술된 **유일한** 문장이 쉴딩이다 — 「공격성 = 태클·파울 빈도·압박 강도」는 1차 근거가 없는 통설(D)이다. 진화·카드 비교에서 힘·공격성 상승은 **등지고 받기·볼 보호·어깨싸움** 축으로 읽는다. ⚠️ FC26 사실이다 — FC27에서 EA가 다시 확인한 것은 「힘은 계속 중요」(#56)까지이고 공격성·쉴딩 문장은 재확인되지 않았다. 2026-10-12 만잠비 Future Stars Academy II 갈래 비교에서 확인(사용자 질문 「공격성과 힘이 어떻게 동작하는지」).','https://www.ea.com/games/ea-sports-fc/fc-26/news/pitch-notes-fc26-title-update-1-4-0 · https://www.ea.com/games/ea-sports-fc/fc-26/news/pitch-notes-fc26-gameplay-deep-dive','A — EA 1차 원문 직접 확인(2026-10-12). 다국어 통설(영·독·서·일)은 fifauteam 문구의 번역·재서술이라 교차검증으로 세지 않았다.','2026-10-12','힘·공격성 = 쉴딩·몸싸움');
INSERT INTO game_system_changes VALUES(54,'FC26','attributes','⭐ 짧은 패스·긴 패스·커브가 높으면 Incisive Pass 없이도 **상황에 따라 스루패스에 커브가 들어간다**(TU 1.5.0). 같은 패치에서 땅볼 패스 정확도·속도를 개선했고 효과는 패스 능력치가 높을수록 크다.','EA 원문: 「Added the ability for players without the Incisive Pass PlayStyle but with high attributes in Short Pass, Long Pass, and Curve to contextually curve through balls」(Incisive Pass PlayStyle이 없어도 짧은 패스·긴 패스·커브 능력치가 높은 선수는 상황에 따라 스루패스에 커브를 넣을 수 있게 했다) · 「Improved accuracy and speed of ground passing, with impact being most noticeable on players with higher passing attributes」(땅볼 패스의 정확도와 속도를 개선했고, 패스 능력치가 높은 선수에게서 효과가 가장 두드러진다).','긴 패스는 「롱볼 전용」이 아니라 **스루패스 커브 조건의 한 축**이다(짧은 패스·커브와 묶임). ⚠️ 「high」의 문턱은 비공개 · 시야(Vision)는 이 조건에 없다. 스루패스 정확도 전반을 어느 능력치가 정하는지는 FC 계열 1차 근거가 없다(FIFA 21의 「짧은/긴 패스+시야+침착」은 구버전 — FC27 행 참조). ⚠️ FC26 사실을 FC27에 전용하는 것은 추정이다. 2026-10-12 만잠비 FSA II 갈래 비교에서 확인.','https://www.ea.com/games/ea-sports-fc/fc-26/news/pitch-notes-fc26-title-update-1-5-0','A — EA 1차 원문 직접 확인(2026-10-12).','2026-10-12','패스 능력치가 높으면 스루패스에 커브');
INSERT INTO game_system_changes VALUES(55,'FC27','attributes','⛔ 시야(Vision)는 FC25~FC27 EA 1차 자료에 **작용 서술이 없다**(부재 증거) — FC27 Gameplay Deep Dive·Ratings Deep Dive·Closed Beta Feedback·FC26 Gameplay Deep Dive 어디에도 능력치로서 등장하지 않는다. 스루패스 품질 요소라는 1차 근거는 **FIFA 21뿐**이다.','FIFA 21 Gameplay Deep Dive(ea.com 원문은 리다이렉트 · 전재본 확인): 「in FIFA 21, a through pass is a mix of Short/Long Passing, Vision and Composure attributes」(FIFA 21에서 스루패스는 짧은/긴 패스·시야·침착 능력치의 혼합이다). FC27은 오히려 조작 보조를 줄였다: 「ground and lobbed through passes no longer heavily assist you by steering toward open lanes away from your aim」(땅볼·로브 스루패스는 더 이상 조준을 벗어나 빈 레인 쪽으로 크게 보정해 주지 않는다) — 이는 조작 보조 설명이지 능력치 정의가 아니다.','역할 가중표(game_role_key_attrs)가 cam_playmaker·cm_playmaker·dm_dlp 등에 시야 ●●●를 준 것은 **판단값(MEDIUM)**이고 FC 계열 1차 근거가 없다 — 진화·카드 비교에서 시야 상승을 「스루패스가 좋아진다」로 단정하지 않는다(쓰려면 FIFA 21 근거·구버전임을 밝힌다). 반응력(#25)과 같은 부재 증거 축. 2026-10-12 만잠비 FSA II 갈래 비교에서 확인.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive · https://www.ea.com/games/ea-sports-fc/fc-26/news/pitch-notes-fc26-gameplay-deep-dive · https://www.fifaultimateteam.it/en/fifa-21-gameplay-official-details-pitch-notes/ (FIFA 21 원문 전재)','A(부재) — FC26·FC27 원문 직접 대조(2026-10-12). FIFA 21 문장은 전재본 경유라 원문 링크 사멸.','2026-10-12','시야는 EA 1차 작용 서술이 없다');
INSERT INTO game_system_changes VALUES(56,'FC27','engine','어깨싸움(Shoulder Challenge) 개편 — **나란히 붙었을 때 가장 효과적**이고, 쫓아가며 연타하면 팔을 내밀며 **속도를 잃는다**. 힘은 계속 중요한 역할을 하고 Bruiser가 추가 이점을 준다(Bruiser+ 추가분은 소폭 축소 — #13).','EA 원문: 「Shoulder Challenges should be most effective when the defender gets side-by-side with the ball carrier」(어깨싸움은 수비수가 볼 소유자와 나란히 섰을 때 가장 효과적이어야 한다) · 「repeatedly pressing Shoulder Challenge in quick succession will cause the defender to stick out an arm and lose speed」(어깨싸움을 빠르게 연타하면 수비수가 팔을 내밀고 속도를 잃는다) · 「Strength continues to play an important role, with the Bruiser PlayStyle providing an additional benefit」(힘은 계속 중요한 역할을 하며 Bruiser PlayStyle이 추가 이점을 준다).','힘 상승의 가치는 FC27에서도 유지된다(A) — FC26 #53(쉴딩·박스아웃·어깨싸움 힘 차이)의 FC27 측 재확인은 **「힘은 계속 중요」 한 문장까지**다. 수비 쪽 연타 압박은 약해졌으므로 볼 소유자(공격형 미드)의 힘은 「나란히 붙는 정상 타이밍의 어깨싸움」에서 의미가 있다. 2026-10-12 만잠비 FSA II 갈래 비교 중 원문 대조에서 확인(기존 적재 누락분).','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-closed-beta-feedback-update (2026-09-03)','A — EA 1차 원문 직접 확인(2026-10-12).','2026-10-12','어깨싸움 개편 — 나란히 붙을 때 가장 효과적');
INSERT INTO game_system_changes VALUES(57,'FC27','positioning','⭐ EA Launch Feedback Update(10-13) — **풀백 조기 하강은 13일이 지나도 「감시·조사 중」**이고 수정 일정이 없다. 킥오프 직후 골·저수비 스탯 인터셉트·니어포스트 로우드리븐·파울 판정도 같은 상태로 재확인됐다. #45·#46·#47의 재확인이며, 「풀백 위치는 게임플레이 전체 균형에 직접 영향을 주므로 변경에 신중하겠다」는 입장이 추가됐다.','en 「fullbacks are dropping too deep while defending, causing issues with defensive structure」(풀백이 수비 시 너무 깊이 내려와 수비 구조에 문제를 일으킨다) · 「Fullback positioning directly affects the overall balance of gameplay」(풀백 위치는 게임플레이 전체 균형에 직접 영향을 준다 — 그래서 변경에 신중하다) · 킥오프 골·인터셉트·로우드리븐·파울은 「monitoring / investigating」(감시 중·조사 중) 유지. ⚠️ de/pt-br 로케일도 영어 본문만 제공 — 교차검증 불가(불변규칙 10 예외 사유).','limit #30(LB att_wb vs 윙백 A/B 결론 유보)의 유효 기간이 길어진다 — Season 2 안 수정 가능성 낮음. 리드 국면 프리셋에 Deep을 쓸 때 풀백이 CB보다 더 내려가는 부작용을 함께 센다. 빌라 구현 판단 5건(obs#1123 보류)을 바꿀 근거는 아니다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-launch-feedback-update (2026-10-13)','A (EA 1차 · 2026-10-22 직접 열람 · reports/research/2026-10-22-fc27-system-gap-review.md §2 ⒜1)','2026-10-22','풀백 조기 하강 여전히 조사 중(10-13)');
INSERT INTO game_system_changes VALUES(58,'FC27','meta','⭐ 케미스트리 개편 **EA 원문 확보(A)** — ICON 국적 기여 +2→+1(모든 리그 +1 링크·자리에 맞으면 풀 케미 유지) · Hero 리그 기여 +2→+1(국적 +1 유지) · Hall of FUT는 Hero와 같은 규칙. #28(B · timesaver 2차)을 1차로 격상한다 — HANDOFF 000⑴ 「원문 대조 후 적재」 충족.','「ICONs will continue to receive full Chemistry when played in position and provide a +1 League link to every League. Their Nation contribution is being reduced from +2 to +1.」(ICON은 자리에 맞게 기용되면 계속 풀 케미스트리를 받고 모든 리그에 +1 리그 링크를 제공한다. 국적 기여는 +2에서 +1로 축소된다.) · 「Heroes will also continue to receive full Chemistry when played in position, while their League contribution is being reduced from +2 to +1. Their +1 Nation contribution remains unchanged. Hall of FUT Items will follow the same Chemistry rules as Heroes.」(Hero 역시 자리에 맞게 기용되면 계속 풀 케미스트리를 받으며, 리그 기여는 +2에서 +1로 축소된다. 국적 +1 기여는 변하지 않는다. Hall of FUT 아이템은 Hero와 동일한 케미스트리 규칙을 따른다.)','케미 상수 변경 없음 — sbc_solve.chem_total은 규칙 대신 fut.gg `player_card_items.chem_extra`를 읽으므로(#28 impact · migration 044 방침) 코드 수정이 없다. 재검산은 다음 /club-sync 회차의 케미 신호 수집이 그대로 수행한다. 000⑴ 종료.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-launch-update (2026-09-14)','A (EA 1차 · 피치노트 원문 직접 확인 2026-09-21·10-22 · reports/research/2026-10-22-fc27-system-gap-review.md §2 ⒜2)','2026-10-22','케미 개편 EA 원문 확보');
INSERT INTO game_system_changes VALUES(59,'FC27','meta','캠페인 선수 아이템은 **해당 포지션의 Role++ 전부를 해제한 채** 출시된다(OTW도 동일) — #21(2차 인용 MEDIUM)을 EA 원문으로 보강. 범위는 「Campaign Player Items」(캠페인 선수 아이템)이며, FUT Deep Dive의 「all special Items」(리서치 §4.4)와 합치면 스페셜 전체.','「all Campaign Player Items will launch with all of their position''s Roles++ unlocked」(모든 캠페인 선수 아이템은 해당 포지션의 Role++ 전부를 해제한 채 출시된다)','docs/22 §6.1 「역할 숙련은 판정 층에서 제외」 유지 — 스페셜·캠페인 카드는 Role++가 일괄 부여돼 변별력이 없다. 베이스 골드 카드(스즈키·헤밍스 등 진화 대상)에서만 Role++가 의미를 가지므로, 진화 갈림길(§6.2)에서만 「Role++ 가지는 긴급성 축」으로 적는다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-launch-update (2026-09-14)','A (EA 1차 · reports/research/2026-10-22-fc27-system-gap-review.md §2 ⒜3)','2026-10-22','캠페인 아이템은 Role++ 전부 해제로 출시');
INSERT INTO game_system_changes VALUES(60,'FC27','playstyles','⭐ **Incisive Pass에서도 리시버 트래핑 오차 감소가 제거**됐다 — #22(핑드 패스·티키타카)의 확장. 「패서의 PlayStyle로 리시버의 퍼스트 터치를 덮는」 경로가 패스 PlayStyle 3종 전부에서 끊겼다.','커뮤니티 정리 「FC 27 removes the previous reduction to the receiver''s trapping error」(FC 27은 종전의 수신자 트래핑 오차 감소를 제거했다 · Operation Sports/timesaver · B) · EA 공식 설명은 「More accurate through balls, more swerve curve, and faster precision passes」(스루패스 정확도·스워브 커브·정밀 패스 속도)로 **수신자 효과가 없다**(EA what-are-playstyles 2026-09-25 · A — 부재 증거).','docs/22 §6.1 규약(패서 PlayStyle로 리시버를 덮지 않는다)이 Pinged·Tiki Taka·Incisive 3종 전부에 적용된다 — 바클리·고메스·맥긴의 「연결」 평가에서 Incisive+ 가산을 쓰지 않는다. reproduction_limits FC27에 같은 취지의 한계 행을 둔다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/what-are-playstyles (2026-09-25) · Operation Sports / timesaver.gg FC27 PlayStyle 정리 (2026-10-22 열람)','B(커뮤니티 정리) + A(EA 설명에 수신자 효과 부재) · reports/research/2026-10-22-fc27-system-gap-review.md §2 ⒜4','2026-10-22','인사이시브 패스의 수신 보정도 제거');
INSERT INTO game_system_changes VALUES(61,'FC27','playstyles','PlayStyle 총수 **36종 확정**(Scoring 8 · Passing 6 · Ball Control 5 · Defending 6 · Physical 5 · GK 6) · 삭제·신설 0 · **개명 1: Rush Out → 「1v1 Close Down」(1대1 근접 압박)**(fut.gg slug는 rush-out 유지) · 표기 「Gamechanger」 한 단어. EA 페이지는 「36」이라 쓰고 35만 인쇄(Power Shot 누락) — fut.gg는 36.','EA what-are-playstyles(2026-09-25) 카테고리 표 + fut.gg /playstyles/ (2026-10-22 열람 · 36). 우리 카탈로그(docs/22 §3 · fc_playstyle_ids 31 「Rush Out」(러시 아웃)·37 「Game Changer」(게임 체인저) · fut_club_players 「Rush Out」(러시 아웃) 46장 · player_game_stats FC27 10행)는 옛 이름 — 어휘 드리프트.','저장 행은 고치지 않고 별칭 표 `fc_playstyle_aliases`(migration 121)로 잇는다 · 읽기는 core/playstyles.py · 화면은 playstyle-icons.js psLookup 한 곳 · G35 ⑵가 정본∪별칭 밖 이름을 막는다. FC24~25 잔존 이름(Flair·Trivela·Power Header·Aerial)은 canonical NULL로 「FC27 없음」 표기.','https://www.ea.com/games/ea-sports-fc/fc-27/news/what-are-playstyles (2026-09-25) · https://www.fut.gg/playstyles/ (2026-10-22)','A(EA 목록) / B(fut.gg 36 · slug) · reports/research/2026-10-22-fc27-system-gap-review.md §2 ⒜5','2026-10-22','PlayStyle 36종 확정 · Rush Out 개명');
INSERT INTO game_system_changes VALUES(62,'FC27','meta','출시 초기 밸런스 동결이 **TU v1.0.4(10-07)까지 실행으로 확인**됐고, 10-19 Archetypes(The Grounds 전용)·10-22 Season 2 「FC Heritage」 문서에도 게임플레이·역할·케미 변경 언급이 0이다 — #47의 연장.','TU v1.0.4 「There are no gameplay balance and tuning changes in this update」(이번 업데이트에 게임플레이 밸런스·튜닝 변경은 없다) · Season 2 FC Heritage(10-22) 본문에 gameplay/roles/chemistry 변경 0건(직접 열람) · Archetypes(10-19)는 The Grounds 전용.','처방 재검토 주기 그대로. 패치 감시 회차는 EA 뉴스 색인(/fc-27/news) 전수를 game_system_changes.source와 차집합으로 대조한다(scripts/patch_watch_index.py) — 10-13·10-19·10-22 3건이 10-12 이후 미적재였던 구조적 결손 대응.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc27-title-update-v1-0-4 (2026-10-07) · https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-season-2-fc-heritage (2026-10-22) · https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-the-grounds-developer-archetypes-update (2026-10-19)','A (EA 1차 · reports/research/2026-10-22-fc27-system-gap-review.md §2 ⒜7)','2026-10-22','밸런스 동결 TU 1.0.4까지 확인');
INSERT INTO game_system_changes VALUES(63,'FC27','meta','출시 초기 밸런스 동결이 **TU v1.1.0(10-27)까지 연장**됐다 — 코어 게임플레이 밸런스·튜닝 변경 0. 대신 EA가 **「이번 주 안」에 Gameplay Developer Notes를 내고 그 조정은 다음 TU에 반영**하겠다고 예고했다(출시 후 첫 밸런스 변경의 예고 · #47·#62의 연장).','TU v1.1.0 「There are no gameplay balance and tuning changes in this update」(이번 업데이트에 게임플레이 밸런스·튜닝 변경은 없다) · v1.1 Pitch Notes 「Later this week we will release another set of Gameplay Developer Notes … along with some discussion about potential adjustments that will follow in our next Title Update」(이번 주 후반에 게임플레이 개발자 노트를 내고, 다음 타이틀 업데이트에 이어질 조정 가능성을 논의하겠다) · 게임플레이 항목은 튜토리얼 정지·PC 키보드 GK 마우스·2v2/1v1/3v3 버그만. ⚠️ ko-kr·ja-jp·de-de 로케일도 영어 본문만 제공 — 다국어 교차검증 불가(불변규칙 10 예외 사유 · #57과 같음).','AVL 팀 전술·처방(match_game_setups·prescriptions) **변경 불필요** — 역할·라인·팀 프레스·PlayStyle 수치가 하나도 안 바뀌었다. ⭐ 다음 패치 감시는 **Gameplay Developer Notes(10-27 주)** 를 최우선으로 본다 — 풀백 조기 하강(#57)·저수비 인터셉트(#46)·킥오프 골이 조정 후보로 거론될 가능성이 높고, 그때 #30 유보 결론과 리드 국면 Deep 프리셋을 재검토한다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc27-title-update-v1-1-0 (2026-10-27) · https://www.ea.com/games/ea-sports-fc/fc-27/news/update-v1-1-pitch-notes (2026-10-26)','A (EA 1차 · 2026-10-27 직접 열람)','2026-10-27','밸런스 동결 TU 1.1.0까지 연장 · 개발 노트 예고');
INSERT INTO game_system_changes VALUES(64,'FC27','tactics','FUT·커리어의 **새 전술 저장 버그 수정** — 새로 만든 전술이 잘못 저장되고 **일부 선수가 엉뚱한 포지션으로 옮겨지는** 문제(FUT)와, 팀 관리에서 새 전술 저장 후 선수가 잘못된 포지션에 놓이는 문제(커리어)를 고쳤다. 팀 관리 화면에 Player Role이 **최대 5개까지만 표시**되던 문제도 함께 수정.','TU v1.1.0 Ultimate Team 「In some cases, new tactics could be saved incorrectly and some players could be moved into the wrong positions」(일부 경우 새 전술이 잘못 저장되고 일부 선수가 잘못된 포지션으로 옮겨질 수 있었다) · Career 「players could be placed in the wrong positions in the formation after creating and saving a new tactic from the Team Management screen」(팀 관리 화면에서 새 전술을 만들어 저장하면 선수가 포메이션의 잘못된 위치에 놓일 수 있었다) · General 「Only up to 5 Player Roles could be displayed in the Team Management screen」(팀 관리 화면에 Player Role이 5개까지만 표시됐다). ⚠️ ko-kr·ja-jp·de-de 로케일도 영어 본문만 제공 — 다국어 교차검증 불가(불변규칙 10 예외 사유 · #57과 같음).','⚠️ 10-27 패치 **이전에 새로 저장한** 커스텀 전술(fut_tactics 2026-10-27T10:13 행 · QxpaxCTYN%8R · 4-1-2-1-2 (2) · EA last_updated 01:11Z)은 인게임 배치가 의도와 다를 수 있었다 — 21:13 싱크의 새 코드(NxmX27PVKL5% · 12:11Z 저장)로 이미 다시 저장됐으므로 지금 활성 전술은 패치 후 저장분이다. 사용자에게 인게임 스쿼드 화면에서 선수 위치를 한 번 확인하도록 안내. 전술 처방 값(역할·포커스·라인) 자체는 영향 없음.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc27-title-update-v1-1-0 (2026-10-27)','A (EA 1차 · 2026-10-27 직접 열람)','2026-10-27','새 전술 저장 버그 수정(TU 1.1.0)');
INSERT INTO game_system_changes VALUES(65,'FC27','evolution','진화·SBC 화면 표시 버그 수정 — ⑴ 패스웨이 진화 **미리보기에서 엉뚱한 스탯이 녹색(상승)으로 강조**되던 문제 ⑵ GK 진화 미리보기에서 상승 스탯이 강조되지 않던 문제 ⑶ 간소화 SBC에 낸 **SBC 스토리지 선수가 다른 SBC에 잠시 계속 보이던** 문제. 스탯 자체·진화 보상·SBC 규칙 변경은 0.','TU v1.1.0 Ultimate Team 「In certain cases when previewing Pathway Evolutions, the incorrect stats could appear highlighted in green」(일부 경우 패스웨이 진화 미리보기에서 잘못된 스탯이 녹색으로 강조될 수 있었다) · 「When applying an Evolution to a Goalkeeper, the upgraded stats in the preview would not be highlighted in green」(GK에 진화를 적용할 때 미리보기에서 상승 스탯이 녹색으로 강조되지 않았다) · 「SBC Storage Player Items that were submitted into Simplified SBCs could still temporarily appear for when completing other SBCs」(간소화 SBC에 제출한 SBC 스토리지 선수 아이템이 다른 SBC를 완료할 때 잠시 계속 나타날 수 있었다). ⚠️ ko-kr·ja-jp·de-de 로케일도 영어 본문만 제공 — 다국어 교차검증 불가(불변규칙 10 예외 사유 · #57과 같음).','우리 진화 비교·원장은 인게임 미리보기가 아니라 카탈로그 상한 적용(core/futgg_attrs.apply_upgrades)과 EA 싱크 실측을 쓰므로 **수치 영향 없음**. 10-27 이전 인게임 미리보기 스크린샷을 근거로 받은 「오른 스탯」 보고는 잘못 강조됐을 수 있다(사용자 보고와 싱크값이 갈리면 싱크 우선). SBC 스토리지는 원장이 제출 시 status=''used''로 내리므로 영향 없음.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc27-title-update-v1-1-0 (2026-10-27)','A (EA 1차 · 2026-10-27 직접 열람)','2026-10-27','진화·SBC 화면 표시 버그 수정');
INSERT INTO game_system_changes VALUES(66,'FC27','meta','Ultimate Scream(10-23~ 2주) 한정 규칙 — **2026-11-24부터 1주일간 모든 Ultimate Scream 선수 아이템이 일시 변신**: 페이스 스탯 하나가 **99**가 되고, **자리만 맞으면 케미 풀(3)** 을 받는다(아이콘·히어로식 무조건 케미). 토큰 스토어 진화 2종(수비 스탯 강화 · 측면 선수 PlayStyle+) 공개.','「all Ultimate Scream Player Items will undergo a temporary transformation for one full week, starting November 24, 2026. This limited-time upgrade will boost a single face stat to 99 and reward the player with full in-position Chemistry」(모든 Ultimate Scream 선수 아이템이 2026-11-24부터 한 주 동안 일시 변신한다 — 페이스 스탯 하나를 99로 올리고 자리에 맞으면 풀 케미를 준다) · 「The first upgrades a player’s defensive stats, while the second offers a PlayStyle+ to a wide player」(첫째는 수비 스탯을 올리고 둘째는 측면 선수에게 PlayStyle+를 준다). ⚠️ ko-kr·ja-jp·de-de 로케일도 영어 본문만 제공 — 다국어 교차검증 불가(불변규칙 10 예외 사유 · #57과 같음).','⚠️ 보유 US 카드 4장(Woltemade·Chong·Lukeba·Vobian) — 11-24~12-01 동안 우리 케미 계산(core/chem.per_player)은 이 카드를 일반 카드로 세어 **케미를 낮게** 잡는다(아이콘·히어로만 무조건 3). 그 주 SBC 해법·스쿼드 케미가 실제보다 보수적으로 나온다 → 11-24 전에 기간 한정 규칙 반영 필요(후속 과제). 99 페이스 스탯은 어느 스탯인지 미공개.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-ultimate-scream (2026-10-23)','A (EA 1차 · 2026-10-27 직접 열람)','2026-10-27','Ultimate Scream 한정 변신 규칙');
INSERT INTO game_system_changes VALUES(67,'FC27','positioning','⭐⭐ EA October Gameplay Developer Notes(10-28) — 출시 후 **첫 게임플레이 밸런스 변경을 TU v1.2.0(11월 중순 · 정확한 날짜 미정)으로 예고**했다. 5항목: ⑴ **풀백이 수비 라인을 더 일관되게 유지**하고 실제 공격 위협이 있을 때만 침투를 따라간다(#45·#57의 수정) ⑵ 공격수의 **오프사이드 인지** 개선(라인을 읽고 온사이드 침투) ⑶ 공격 AI가 박스 주변 빈 공간으로 더 결단력 있게 지원 침투 ⑷ **킥오프 직후 수비 라인을 더 높게 유지**(킥오프 골 감소) ⑸ 루즈볼 자동 스위칭 수정(슬라이드 태클 뒤·헤딩 패스 뒤·빗나간 슛 뒤). ⚠️ **예고이지 적용이 아니다** — 10-29 현재 엔진은 v1.1.0 그대로(#63).','「Our next Title Update in mid-November will introduce our first set of gameplay balance changes for FC 27.」(11월 중순 다음 타이틀 업데이트가 FC 27의 첫 게임플레이 밸런스 변경을 도입한다.) · 「Fullbacks will hold their defensive line more consistently, moving to track runs when there''s a genuine attacking threat.」(풀백은 수비 라인을 더 일관되게 유지하고, 실제 공격 위협이 있을 때 침투를 따라 움직인다.) · 「this behaviour may still occur occasionally, but overall consistency has been noticeably improved」(이 동작은 여전히 가끔 일어날 수 있지만 전체적인 일관성은 눈에 띄게 개선됐다) · 「the defensive line will hold a higher position after kick-off」(킥오프 뒤 수비 라인이 더 높은 위치를 유지한다) · 「we''ve refined attacking awareness to help attackers better recognise the defensive line」(공격수가 수비 라인을 더 잘 인식하도록 공격 인지를 다듬었다). ⚠️ ko·de·ja 로케일도 영어 본문만 제공 — 다국어 교차검증 불가(불변규칙 10 예외 사유 · #57·#63과 같음).','⭐ **v1.2.0 적용 전후가 갈리는 경계가 생긴다.** ⑴ #45·#57의 풀백 조기 하강이 고쳐지면 에메리 재현의 전제(높은 라인 + 풀백 라인 유지)가 엔진에서 복원된다 → limit #30(LB att_wb vs 윙백 유보)·obs#449 양 풀백 판정·FC27 슬롯 정본 보류 중 「LB 저점유 운용」은 **패치 뒤 실측으로 재판정**하고, 패치 전 표본과 섞지 않는다. ⑵ HANDOFF P1 「FC27 첫 인게임 캡처(T6·T7)」는 **v1.2.0 전에 찍으면 패치 전 기준선**이 된다 — 풀백 조기 하강을 고정 관측 항목(#45 impact)으로 함께 센다. ⑶ 리드 국면 Deep 프리셋의 「풀백이 CB보다 더 내려가는 부작용」(#57)은 패치 뒤 다시 센다. ⑷ 오프사이드 인지 개선은 상대 공격수에도 적용되므로 높은 라인의 오프사이드 트랩 효율이 떨어질 수 있다(EA 서술 범위 밖 추론 — 실측 전 처방 근거로 쓰지 않는다). ⛔ 처방·`team_tactic_setups` 정본은 **패치 적용 확인 전 바꾸지 않는다**(#45 원칙 유지).','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc27-october-gameplay-developer-notes (2026-10-28)','A (EA 1차 · 2026-10-29 직접 열람) · 적용 여부는 미확인(예고) — v1.2.0 패치노트가 나오면 실제 반영 항목을 새 행으로 확정한다','2026-10-29','TU 1.2.0 첫 밸런스 패치 예고(풀백 라인 등 5항목)');
INSERT INTO game_system_changes VALUES(68,'FC27','tactics','EA가 같은 글에서 **v1.2.0에 넣지 않은 「조사 중」 3건**을 밝혔다: ⑴ **높은 수비 라인이 상대에게 지나친 압박을 주는 상황** ⑵ 체격·피지컬이 다른 선수 간 충돌 처리 ⑶ 특정 슛 종류의 정확도 + GK 위치. 함께 공개한 출시 1개월 실측: 슛은 줄고 득점 효율은 올랐다 · 패스 수는 약간 줄고 성공률은 올랐다(수동 수비 인터셉트는 약간 증가) · 태클 성공 증가 · **포메이션별 승률이 고르게 분포(편차 최소)**하고 FC26 대비 전술·역할 다양성이 늘었다.','「Situations where high defensive lines can put too much pressure on the opposition」(높은 수비 라인이 상대에게 지나친 압박을 줄 수 있는 상황) · 「Looking at how collisions between players of different sizes and physical attributes are handled」(체격·피지컬 속성이 다른 선수 간 충돌이 어떻게 처리되는지 보고 있다) · 「win rates by formation are evenly distributed with minimal variance」(포메이션별 승률은 편차가 최소로 고르게 분포한다) · 「manually-controlled defenders intercepting slightly more often」(수동 조작 수비수의 인터셉트가 약간 더 잦다). ⚠️ ko·de·ja 로케일도 영어 본문만 제공 — 다국어 교차검증 불가(불변규칙 10 예외 사유 · #57·#63과 같음). ⚠️ 커뮤니티(outputlag · r/EASportsFC 정리)는 수비 깊이 95 라인 메타가 v1.2.0에 빠졌다고 지적한다 — **D(통설)** 이고, EA의 「high defensive lines」(높은 수비 라인) 조사 항목이 그것을 가리키는지는 EA가 밝히지 않았다.','⑴ **높은 라인 너프 가능성이 EA 공식 조사 항목이 됐다(A · 일정 없음).** AVL FC27 정본 #46(Balanced/Balanced/라인 52)은 High 구간이 아니라 직접 대상은 아니지만, 압박·고라인 국면 프리셋(`optimal:lead` 등 보류 5건)을 High 쪽으로 옮기는 판단에는 「후속 패치에서 약화될 수 있다」는 리스크를 병기한다. 커뮤니티 95 depth 메타(D)는 처방 근거로 쓰지 않는다. ⑵ 포메이션 승률 평준화(A)는 「메타 포메이션으로 바꿔야 이긴다」는 근거가 약하다는 뜻 — 실축 재현 포메이션 유지 방침과 부딪히지 않는다. ⑶ 저수비 스탯 인터셉트 과효율(#46)은 v1.2.0 항목에도 조사 목록에도 없다 → #46 impact(한시적 · 수정 예고 없음) 유지. ⑷ 체격 충돌 조사는 피지컬 진화 선택(가성비)의 FC27 전제가 바뀔 수 있는 축 — 결과가 나오면 docs/22 §2.1과 진화 처방을 다시 본다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc27-october-gameplay-developer-notes (2026-10-28) · https://outputlag.com/news/ea-fc-27s-first-gameplay-patch-lands-mid-november-and-the-95-depth-meta-isnt-in-it/ (커뮤니티 · D)','A (EA 1차 · 2026-10-29 직접 열람) — 95 depth 메타 부분만 D(통설 · 커뮤니티 정리)','2026-10-29','TU 1.2.0 밖 조사 중 3건 · 출시 1개월 실측');
INSERT INTO game_system_changes VALUES(69,'FC27','tactics','⭐⭐ EA 게임플레이 개발팀이 1차 Discord Q&A(10-09 게시 정리)에서 **커뮤니티의 「수비 깊이 95」 질문에 직접 답했다** — 오프사이드 트랩 남용을 막는 방법과 **수비 라인 깊이 재조정**을 보고 있지만, 대응법을 익힌 플레이어가 있고 밸런스 영향이 커서 **안정화 시간을 두는 중**이라고 했다(일정 없음). 같은 Q&A에서 ⑴ 풀백 라인 문제는 **「잠재적 해법을 찾아 테스트 중」**(10-09 시점 — 이것이 #67의 v1.2.0 풀백 항목으로 나왔다) ⑵ 킥오프는 **킥오프 직후 수비 라인이 얼마나 깊이 내려가는지** 감시 중이라고 답했다(#67 킥오프 항목의 원인 서술). ⇒ #68 「high defensive lines」(높은 수비 라인) 조사 항목과 **같은 축일 가능성이 높다**(EA가 두 글을 직접 연결하지는 않았다 — 연결은 추론).','질문 요지(Q7): 수비 깊이 95를 계속 유지해도 스태미나가 줄지 않는다. · 「We are looking at ways to prevent spamming offside traps as well as rebalancing the depth of the defensive line.」(오프사이드 트랩 남용을 막는 방법과 수비 라인 깊이를 재조정하는 방법을 보고 있다.) · 「We''ve seen certain players learn how to counter this strategy, so, because making a change here would also impact the balance of the game, we are giving time for the game to settle.」(일부 플레이어가 이 전략에 대응하는 법을 익히는 것을 봤고, 여기를 바꾸면 게임 밸런스에도 영향을 주므로 게임이 자리 잡을 시간을 두고 있다.) · Q4 「We have already identified a potential solution and we are currently testing it.」(이미 잠재적 해법을 찾았고 현재 테스트 중이다.) · Q2 「we are monitoring how deep the defensive line can drop after kick off」(킥오프 뒤 수비 라인이 얼마나 깊이 내려갈 수 있는지 감시하고 있다). ⚠️ 95 depth의 **스태미나 비소모 여부 자체에는 답하지 않았다** — 「95에서도 스태미나가 안 준다」는 질문자 주장이고 D(통설)로 둔다.','⑴ **높은 라인·오프사이드 트랩 너프가 EA 개발자 입으로 확인된 검토 항목이 됐다(A · 일정 없음).** AVL FC27 전술 정본(`team_tactic_setups` #46 · Balanced/Balanced/라인 52)은 직접 대상이 아니다. 단 에메리 재현의 **오프사이드 트랩(높은 라인 + 라인 일제 전진)** 을 FC27에서 고라인 프리셋으로 강화하려는 판단(보류 5건 · `optimal:lead` 등)에는 「후속 패치에서 깊이 상한·트랩 효율이 깎일 수 있다」를 리스크로 병기한다(#68과 같은 결론을 A 근거로 보강). ⑵ 커뮤니티 95 depth 메타·「95에서 스태미나 비소모」는 D — 처방 근거로 쓰지 않는다. ⑶ 풀백 해법이 10-09에 이미 테스트 중이었다는 점은 #67(v1.2.0) 적용 가능성을 높이지만, 처방·`team_tactic_setups` 정본은 **패치 적용 확인 전 바꾸지 않는다**(#45 원칙).','https://steamcommunity.com/app/4080220/discussions/0/588440114694207040/ (「FC 27 - Gameplay Developer Q&A Responses」 · 작성자 EA_Vendcera(EA 커뮤니티 매니저) · 2026-10-09 17:12 UTC 게시 · 공식 Discord 1차 게임플레이 Q&A 정리)','A (EA 1차 — EA 커뮤니티 매니저가 개발자 답변을 정리한 공식 전사 · 2026-10-31 직접 열람) · ⚠️ 10-30 2차 Q&A가 아니라 **10-09 게시 1차 Q&A**다 · 단일 공식 정리라 교차검증 대상 없음(번역본·현지어 정리 미발견)','2026-10-31','수비 깊이 95 재조정 검토(1차 Q&A)');
INSERT INTO game_system_changes VALUES(70,'FC27','attributes','EA가 1차 Discord Q&A(10-09 게시 정리)에서 **「작고 가벼운 선수가 크고 힘센 선수를 공에서 밀어내는」 경우가 있다**고 인정하고 더 현실적인 균형을 검토 중이라고 답했다(질문은 여성 선수 키·민첩 대비 힘 문제). #68의 「체격·피지컬이 다른 선수 간 충돌 처리」 조사 항목의 구체 증상이다 — **v1.2.0 항목에는 없다**.','「In some instances a shorter, lighter player would push a taller, stronger player away from the ball.」(어떤 경우에는 더 작고 가벼운 선수가 더 크고 힘센 선수를 공에서 밀어낸다.) · 「We are currently looking into creating a more realistic balance in those situations.」(그런 상황에서 더 현실적인 균형을 만드는 것을 검토하고 있다.)','⑴ FC27 현행(v1.1.0) 엔진에서 **힘(Strength)·키·체중의 몸싸움 우위가 기대만큼 작동하지 않는 경우가 있다**는 EA 인정(A · 「some instances」(어떤 경우에는) — 빈도·조건 미공개). ⇒ 진화 선택에서 **힘 증가만을 근거로 한 피지컬 진화의 가성비**는 수정 전까지 한 단계 낮춰 본다(docs/22 §2.1의 FC26 근거를 FC27에 전용할 때 이 행을 병기). ⑵ AVL 처방에서 체격형 선수(타깃형 ST·CB 몸싸움)의 역할 판단은 **바꾸지 않는다** — 증상 범위가 불명확하고 수정이 예고돼 있다. 수정 패치가 나오면 docs/22와 진화 처방을 다시 본다.','https://steamcommunity.com/app/4080220/discussions/0/588440114694207040/ (「FC 27 - Gameplay Developer Q&A Responses」 · 작성자 EA_Vendcera(EA 커뮤니티 매니저) · 2026-10-09 17:12 UTC 게시 · 공식 Discord 1차 게임플레이 Q&A 정리)','A (EA 1차 — EA 커뮤니티 매니저가 개발자 답변을 정리한 공식 전사 · 2026-10-31 직접 열람) · ⚠️ 10-30 2차 Q&A가 아니라 **10-09 게시 1차 Q&A**다 · 단일 공식 정리라 교차검증 대상 없음(번역본·현지어 정리 미발견)','2026-10-31','작은 선수가 큰 선수를 밀어내는 문제 인정');
INSERT INTO game_system_changes VALUES(71,'FC27','engine','EA 1차 Discord Q&A(10-09 게시 정리)의 조작·AI 답변: ⑴ **FC27 스루 패스는 FC26보다 수동화**됐다(FC26은 보정이 커서 역습 기회가 과다) · 땅볼 패스도 튜닝이 약간 다르며 데이터상 플레이어가 인터셉트와 패스의 균형을 익히는 중 ⑵ **드리블은 역대 가장 반응이 빠르고**, 상위 숙련도에서 비현실적 사용(연속 방향 전환)이 나온다 — 반응성을 전반적으로 낮추지 않는 해법을 논의 중 ⑶ 선수 전환(오른쪽 스틱·L1)은 계속 개선 탐색 ⑷ Authentic 모드 CPU 공격 빈약 피드백을 검토 중. 모두 **일정 없음**.','「In FC26 through passes were more assisted creating too many counter attack opportunities. Through passes are now more manual to create more opportunities for users to express their skill.」(FC26에서는 스루 패스 보정이 더 커서 역습 기회가 너무 많았다. 이제 스루 패스는 더 수동이 되어 사용자가 실력을 드러낼 기회가 늘었다.) · 「our data shows that players are learning the balance between interceptions and passing」(데이터는 플레이어들이 인터셉트와 패스 사이의 균형을 익히고 있음을 보여준다) · 「in FC27 Dribbling is the most responsive ever. However, at a certain skill level Dribbling is so responsive that it allows the users to use the mechanic in unrealistic ways.」(FC27의 드리블은 역대 가장 반응이 빠르다. 다만 일정 숙련도에서는 반응이 너무 빨라 비현실적인 방식으로 쓸 수 있다.) · 「We are currently discussing potential solutions that don''t reduce the responsiveness in general.」(반응성을 전반적으로 낮추지 않는 해법을 논의 중이다.)','⑴ ⭐ 버전 차이(A): **스루 패스 보정 축소는 FC26→FC27 변경** — FC26 시절 「스루 패스 역습」 근거를 FC27 처방에 전용하지 않는다. 에메리 재현의 수직 전환(라인 사이 → 침투 스루)은 FC27에서 **조작 정확도에 더 의존**한다. ⑵ 저수비 스탯 인터셉트(#46)에 대해서는 「균형을 익히는 중」이라는 일반론뿐 — **수정 예고가 아니다** → #46 impact(한시적 · 수정 예고 없음) 유지. ⑶ 드리블·전환·Authentic AI는 AVL 전술 처방과 직접 관계 없음(조작·모드 축) — 기록만 한다.','https://steamcommunity.com/app/4080220/discussions/0/588440114694207040/ (「FC 27 - Gameplay Developer Q&A Responses」 · 작성자 EA_Vendcera(EA 커뮤니티 매니저) · 2026-10-09 17:12 UTC 게시 · 공식 Discord 1차 게임플레이 Q&A 정리)','A (EA 1차 — EA 커뮤니티 매니저가 개발자 답변을 정리한 공식 전사 · 2026-10-31 직접 열람) · ⚠️ 10-30 2차 Q&A가 아니라 **10-09 게시 1차 Q&A**다 · 단일 공식 정리라 교차검증 대상 없음(번역본·현지어 정리 미발견)','2026-10-31','스루 패스 수동화 · 드리블 반응성(1차 Q&A)');
INSERT INTO game_system_changes VALUES(72,'FC27','goalkeeping','⭐⭐ GK OVR 산정식은 GK 4속성 균등이다 — round(0.21×(다이빙+핸들링+포지셔닝+반사신경) + 0.11×반응력 + 0.05×킥) + 1. FC27 비특별 기본 GK 카드 90장 중 83장 정확(92%) · 90장 ±1(100%)(2026-11-03 부모 세션 재검산 · 서브에이전트 1차 76/83). 제약 없는 최소제곱도 23.5/22.2/21.0/20.2/10.3/4.2(%)(합 1.013)로 같은 모양이다. 우리 저장 적합값(반사 39·포지셔닝 25·다이빙 18·핸들링 13·반응 5·킥 0 · 2026-10-02)은 같은 표본에서 40/83(48%)이다 — GK 4속성 간 상관 0.91~0.94의 공선성 착시. 스피드(가속·질주)는 OVR 항에 없다. 빗나간 7장(오블락·알리송·픽포드·Cata Coll·마르티네스·Paños·Earps)은 전부 실제가 +1~2 높다(국제 명성 보너스 가설 · 미검증). +1 상수의 정체는 미상(53 OVR 카드에도 붙는다).','db/tactics.db player_card_items(FC27·best_pos=GK·is_special=0) 83장에 산정식 6종을 읽기 전용으로 대조(/tmp/cmp/gkfit.py): 고전 21/21/21/21/11/5+1 → 76 · fifauteam FIFA19 24/22/22/22/6/4+1 → 58 · 저장값 → 40 · GameBoost 30/25/20/15/10 → 33 · 곱셈 보정 ×1.0125 → 70. numpy 최소제곱 재적합.','진화 부풀림(표기 Δ − 세부 스탯 Δ) 계산이 GK에서 틀린다 — 저장 가중치로는 반사 진화의 Δ를 과대평가하고 핸들링·다이빙 진화를 과소평가한다. OVR 1점당 GK 4속성은 같은 값이고, 반응력 +2 ≈ GK 속성 +1, 킥 +4 ≈ GK 속성 +1이다. fc_position_ovr_weights GK 행을 다시 맞추는 근거(행 추가 · 부모 판단).','우리 실측(db/tactics.db player_card_items · 2026-11-03) · 비교 표: https://fifauteam.com/player-ratings-guide-fifa-19/ (2018) · https://gameboost.com/blog/best-goalkeepers-in-ea-fc-27','C — 우리 실측 n=90(재검산)(비특별 기본 카드만). EA 비공개. 진화·특별 카드에는 적용되지 않는다. +1 상수·IR 보너스는 미검증.','2026-11-03','GK OVR 산정식 — 4속성 균등 + 상수 1');
INSERT INTO game_system_changes VALUES(73,'FC27','goalkeeping','FC27 EA 1차 자료에 GK 메커니즘 변경 서술이 0건이다(부재 증거) — Gameplay Deep Dive(07-29)에 goalkeeper·save·parry·rush 언급이 없고, PlayStyle 리밸런스 10종(#13)에도 GK PlayStyle이 없으며, TU v1.0.1~v1.1.0의 GK 항목은 버그 수정뿐이다(PC 마우스 · Clubs 11v11에서 GK 2명 · 진화 미리보기 #65 · 1v1에서 「the Goal Keeper could hold the ball for longer than expected even if a pass had been requested」(「패스를 요청해도 GK가 예상보다 오래 공을 쥐던 문제」)). ⇒ FC27 GK 엔진은 FC26 최종 상태(TU 1.5.x)를 이어받았다고 보는 것이 가장 그럴듯하다(추정 · EA 미확인).','EA FC27 Gameplay Deep Dive · What are PlayStyles · TU v1.1.0 전문을 직접 읽고 GK 관련 문장을 전수 확인(2026-11-03).','FC26 GK 패치 이력(니어포스트 반응 개선 · 잡기/펀칭 판단 · 수동 GK 이동 너프 · 자동 세이브 범위 확대)을 FC27 GK 평가의 전제로 쓸 수 있다. 단 「이월」은 추정이라 그렇게 적는다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive (2026-07-29) · https://www.ea.com/games/ea-sports-fc/fc-27/news/what-are-playstyles (2026-09-25) · https://www.ea.com/games/ea-sports-fc/fc-27/news/fc27-title-update-v1-1-0 (2026-10-27)','A(부재) — 직접 읽음. 「FC26 이월」은 추정(D 수준)이라 분리해 적는다.','2026-11-03','FC27 GK 메커니즘 변경 0건(부재 증거)');
INSERT INTO game_system_changes VALUES(74,'FC27','goalkeeping','EA 밸런스 발언 원문 확보(#47 보강) — 「We''re pretty happy with the current balance between shooting and goalkeeping, but we''ll continue to monitor your feedback and our data for any potential outliers.」(「슈팅과 골키핑 사이 현재 밸런스에 꽤 만족하지만, 이상치가 있는지 피드백과 데이터를 계속 감시하겠다.」) · 「One of our core philosophies is that players should be rewarded for earning a shot from a dangerous area.」(「위험 지역에서 슛 기회를 만든 플레이어는 보상받아야 한다는 것이 핵심 철학 중 하나다.」). 「fairly happy(꽤 만족한다)」는 원문 표현이 아니다. 한국어·스페인어·이탈리아어·포르투갈어판은 같은 원문의 번역이다(교차검증 아님).','EN·KO·ES·IT·PT-BR 페이지를 직접 읽고 해당 문장을 대조. DE·FR URL의 10-28 글은 본문이 영어 그대로.','니어포스트 로우드리븐 슛은 EA가 「위험 지역 슛 보상」 철학으로 정당화하는 영역이다 — v1.2.0에서 GK 쪽이 크게 상향될 거라고 기대하지 말 것(10-28 「조사 중」은 #68).','https://www.ea.com/games/ea-sports-fc/fc-27/news/fc-27-gameplay-developer-launch-update (2026-09-30) · https://www.ea.com/ko/games/ea-sports-fc/fc-27/news/fc-27-gameplay-developer-launch-update · https://www.ea.com/es/games/ea-sports-fc/fc-27/news/fc-27-gameplay-developer-launch-update','A — EA 원문을 직접 읽음. #47의 원문 보강이며 새 사실은 「위험 지역 보상」 철학 문장뿐이다.','2026-11-03','EA 슈팅·GK 밸런스 만족 발언 원문');
INSERT INTO game_system_changes VALUES(75,'FC27','goalkeeping','⭐ 1v1 Close Down(=Rush Out)은 전진만 하는 PlayStyle이 아니다 — EA 레이팅 툴팁 「Unique reflex saves, better close shot reads, greater rush speed」(「고유 반사 세이브, 더 나은 근거리 슛 읽기, 더 빠른 전진 속도」), fut.gg 게임 데이터 「Unique reflex/anticipation save animations, increase in rush speed and improved read of close shot trajectories.」(「고유 반사·예측 세이브 애니메이션, 전진 속도 증가, 근거리 슛 궤적 읽기 향상」). ⚠️ EA 화면끼리 이름이 다르다: PlayStyles 글은 「1v1 Close Down」(1대1 근접 압박)과 일본어판 「1v1接近戦」(1대1 접근전), 레이팅 DB는 「Rush Out+」(뛰쳐나가기+)와 일본어판 「飛び出し+」(뛰쳐나가기+)를 그대로 쓴다(#61 개명이 다 반영되지 않았다).','EA FC27 쿠르투아 레이팅 페이지(Rush Out+ 툴팁)와 fut.gg /playstyles/rush-out/(PlayStyle명 1v1 Close Down · 일반 86 · + 7)을 직접 읽음. JA 레이팅 페이지는 스니펫.','1v1 Close Down(+)은 근거리 선방에도 걸린다 — Joan García(86 · Rush Out+)가 OVR 90 쿠르투아보다 많이 쓰이는 메타를 설명하는 후보(D). GK 진화에서 1v1 Close Down을 주는 가지의 가치를 「스위핑」만으로 매기지 말 것.','https://www.ea.com/games/ea-sports-fc/ratings/player-ratings/thibaut-courtois/192119 (FC27 · 2026-11-03 접속) · https://www.fut.gg/playstyles/rush-out/ (2026-11-03) · https://www.ea.com/ja/games/ea-sports-fc/fc-27/news/what-are-playstyles (2026-09-25)','A(EA 툴팁) + B(fut.gg) — 같은 게임 데이터 계보일 가능성이 커서 독립 교차검증은 아니다. 효과 크기 수치는 없다.','2026-11-03','1v1 Close Down은 근거리 선방도 강화');
INSERT INTO game_system_changes VALUES(76,'FC27','goalkeeping','GK PlayStyle 효과는 슛 종류마다 갈린다(fut.gg 게임 데이터) — Far Reach 「increased chances of saving long distance shots」(「먼 거리 슛 선방 확률 증가」) · Footwork 「increased performance against low trajectory shots」(「낮은 궤적 슛 대응력 증가」) · Deflector 「Increased power to parry shots into safer areas」(「슛을 안전한 곳으로 쳐내는 힘 증가」) · Cross Claimer 「prioritization of punch animations in contested ball scenarios, and increased speed for coming out for crosses」(「경합 상황에서 펀칭 애니메이션 우선, 크로스에 나오는 속도 증가」). EA 레이팅 툴팁의 Far Reach도 「better long shot saves」(「중거리 슛 선방 향상」)다. 보유 수(일반/+, 11-03): Far Reach 81/7 · Footwork 390/2 · Deflector 104/5 · Cross Claimer 246/6 · 1v1 Close Down 86/7.','fut.gg /playstyles/{far-reach,footwork,deflector,cross-claimer}/ 직접 읽음 + EA 쿠르투아 레이팅 툴팁(Far Reach) 대조.','니어포스트·로우드리븐 실점에 맞는 처방은 Far Reach가 아니라 Footwork다(텍스트 기준 · 실측 없음). Cross Claimer는 크로스를 「잡게」 하지 않고 펀칭을 늘린다 — 「크로스 캐치형」으로 오해하지 말 것. docs/22 §3 GK 표의 Far Reach 「다이빙/점프 애니메이션 다양화 + 박스 밖 슛」·Cross Claimer 「캐칭 애니메이션」 서술과 충돌한다.','https://www.fut.gg/playstyles/far-reach/ · https://www.fut.gg/playstyles/footwork/ · https://www.fut.gg/playstyles/deflector/ · https://www.fut.gg/playstyles/cross-claimer/ (2026-11-03) · https://www.ea.com/games/ea-sports-fc/ratings/player-ratings/thibaut-courtois/192119','B — 게임 데이터 텍스트(효과 크기 수치 없음). Far Reach는 EA 툴팁(A)과 일치. 인게임 실측은 0건.','2026-11-03','GK PlayStyle 효과는 슛 종류마다 다르다');
INSERT INTO game_system_changes VALUES(77,'FC26','goalkeeping','FC26 Gameplay Deep Dive의 GK 시스템 — ⑴ Deflection Control 기본값: 「Most deflections will now go out of bounds, toward teammates, or to open space away from opponents.」(「대부분의 쳐낸 공이 라인 밖, 동료 쪽, 상대에게서 떨어진 빈 공간으로 간다.」) — Deflector 없이도 적용 ⑵ RL GK Positioning: 「RL Positioning is only active in certain situations, and is only used to position the Goalkeeper. The system is not active when making a save or performing a catch.」(「RL 포지셔닝은 특정 상황에서 GK 위치를 잡는 데만 쓰이고, 세이브·캐치 중에는 작동하지 않는다.」) ⑶ 핸들링 기반 시스템·1대1 판단 개선 ⑷ Sweeper Keeper 「focused on rushing and coming out to recover balls during defence」(「수비 시 뛰쳐나와 공을 회수하는 데 집중한다」) · Ball-Playing Keeper 「stays on their line when their team is in defense」(「수비 시 라인에 머문다」). GK 속성(다이빙·반사 등)과 키의 작용 서술은 없다.','EA FC26 Gameplay Deep Dive 전문을 직접 읽고 GK 절을 전수 발췌.','GK 포지셔닝 속성이 RL 포지셔닝의 입력인지는 EA가 밝히지 않았다(열린 질문). 역할 선택의 1차 정의(SK=전진 회수 · BPK=빌드업 + 수비 시 라인 유지). FC27 이월은 미확인.','https://www.ea.com/games/ea-sports-fc/fc-26/news/pitch-notes-fc26-gameplay-deep-dive (2025-07-22)','A — 직접 읽음. FC26 사실이며 FC27 적용은 EA가 확인하지 않았다.','2026-11-03','FC26 GK 시스템(쳐내기 제어 등)');
INSERT INTO game_system_changes VALUES(78,'FC26','goalkeeping','FC26 TU의 GK 조정 이력 — 1.1.0(2025-10-23): 「Improved goalkeeper reactions to near post shots.」(「니어포스트 슛에 대한 GK 반응 개선」) · 펀칭 강화 · 공격수 쪽·자책골 방향 쳐내기 감소 · 쓸데없는 자동 전진 수정 / 1.2.0(2025-11-11): 잡는 게 나은 크로스에서 펀칭하던 문제 수정 · 드리블러 근처 다이빙 판단 개선 · 파포스트 원터치 슛 과잉 쏠림 완화 / 1.3.0(2025-12-02): 「Greatly reduced movement speed and amount of ground covered when using Manual Goalkeeper Movement in open play.」(「오픈 플레이 수동 GK 이동의 속도·범위를 크게 줄였다」) · Rush To Center 제거 · 「Slightly increased auto save assistance range across all assistance levels.」(「모든 보조 단계에서 자동 세이브 보조 범위를 약간 넓혔다」) / 1.4.2(2026-02-03): 예측 세이브 중 너무 정확한 쳐내기 수정.','EA 패치노트 원문 문장을 fifauteam TU 이력·futwiz 1.2.0 전문에서 직접 읽음. EA 포럼 원문(1.1.0)은 403이라 스니펫으로만 확인.','FC27 1차 자료에 GK 변경이 0건이라, 이 이력이 FC27 GK 거동의 가장 그럴듯한 출발점이다. 니어포스트 반응은 FC26에서 이미 한 번 상향됐는데도 FC27에서 다시 불만 1순위가 됐다.','https://fifauteam.com/fc-26-title-update/ · https://www.futwiz.com/news/article/fc-26-title-update-full-notes-1-2-0/12658 (2025-11-10) · https://forums.ea.com/blog/ea-sports-fc-game-info-hub-en/fc-26-v1-1-0-update-notes/12815780','A — EA 패치노트 원문(미러 경로). 날짜는 미러 캘린더 기준(연도는 추론). FC27 이월은 미확인.','2026-11-03','FC26 TU의 GK 조정 이력');
INSERT INTO game_system_changes VALUES(79,'FC27','set_pieces','⭐ 코너킥이 2단계(Two phase corners)로 바뀌었다 — 목표 지점·파워를 고르면 카메라가 박스로 옮겨가고, 공이 오기 전 짧은 창에서 공격수를 직접 움직인다(이동·선수 전환·런·쉴딩·Avoidance). 박스 안 선수가 낙하지점으로 **자동으로 가지 않는다**: 「players contesting for corner kicks in the box will no longer automatically move into the best position」(「코너킥 때 박스에서 경합하는 선수는 더 이상 자동으로 최적 위치로 가지 않는다」) · 「It''s up to you to time the run, attack the space, and make first contact manually.」(「런 타이밍·공간 공략·첫 접촉을 직접 해야 한다」). 숏코너는 예외: 「this change does not apply to short corner kicks」(「이 변경은 숏코너에는 적용되지 않는다」).','EA FC27 Gameplay Deep Dive 피치노트(2026-07 말) 원문 직접 읽음. 「connecting with a header from crosses and corners requires greater precision」(「크로스·코너에서 헤더를 맞히려면 더 정밀해야 한다」).','코너 득점은 이제 **수동 조작 기량**이 크게 좌우한다 — 실축 코너 루틴(니어 플릭·스크린·키퍼 방해)을 「전술 설정」만으로 재현할 수 없다. 실축 빌라 코너 분석(reports/research/2026-11-04-avl-set-pieces.md)을 FC로 옮길 때 자동 재현 가능한 축(키커·타깃·러너 수·니어/파 런·수비 지역/대인)과 조작 축을 갈라 적는다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive (2026-11-04 접속)','A — EA 1차(피치노트). 효과 크기 수치 없음.','2026-11-04','코너킥 2단계 · 박스 위치잡기는 수동');
INSERT INTO game_system_changes VALUES(80,'FC27','set_pieces','코너 수비·공격 모두 새 조작 Avoidance(R1/RB 홀드)를 쓸 수 있다: 「This allows any attacker or defender you control to become more evasive」(「조종 중인 공격수나 수비수를 더 잘 빠져나가게 한다」) · 「Pairing this with Shielding allows an attacking player to hold their position after creating space」(「쉴딩과 함께 쓰면 공격수가 공간을 만든 뒤 자리를 지킬 수 있다」).','EA FC27 Gameplay Deep Dive 피치노트 원문. 쉴딩 입력(L2/LT 홀드)은 EA 원문에 없고 커뮤니티 가이드(timesaver.gg·m8x) 서술이다.','인게임 조작 축 — 감독 재현 정본(slot_canon_roles·tactics)에는 들어가지 않는다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive · https://timesaver.gg/blog/fc-27-corners-how-to-score-defend-aerial-fortress-myth','A(Avoidance 동작·입력 R1/RB) · D(쉴딩 입력)','2026-11-04','코너 Avoidance(R1/RB 홀드)');
INSERT INTO game_system_changes VALUES(81,'FC27','set_pieces','세트피스 전술 메뉴가 새로 생겼다(경기 중 D-pad 위). 코너: 세트플레이 인원 추가·제거 · 니어포스트 런 · 파포스트 런 · (수비) 지역 방어 / 대인 방어 전환. 프리킥: 인원 추가·제거 · 니어/파 런 · (수비) 라인 내리기 · 오프사이드 트랩. FC26의 Edge Of Box Run · Crowd the Goalkeeper는 빠졌다. 경기 전에는 팀 관리의 세트피스 키커·타깃 지정이 따로 있다.','EA 원문에는 「the new set piece tactics interface visible」(「새 세트피스 전술 화면이 보인다」)라는 이미지 설명뿐이고 항목은 없다. 항목·입력은 Pro Clubs HQ의 인게임 조작 목록 전사와 timesaver.gg·m8x 가이드가 일치한다(같은 전사 계보일 수 있어 독립 교차검증은 아니다).','⭐ 빌라 실축 코너 수비 방식(지역/대인/혼합)과 공격 러너 수·니어/파 비중을 **이 메뉴의 선택지로 옮길 수 있다**(구현 가능 축). 인게임 화면으로 항목을 확인하면 A로 올린다.','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive · https://proclubshq.com/blog/fc27-control-changes/ · https://timesaver.gg/blog/fc-27-corners-how-to-score-defend-aerial-fortress-myth · https://www.m8x.com/news/fc-27-corner-kicks-how-do-you-actually-score-with-the-new-manual-system.html','D — 커뮤니티 전사(인게임 화면 미확인). 메뉴 존재 자체는 A(EA 이미지 설명).','2026-11-04','세트피스 전술 메뉴 신설(D-pad ↑)');
INSERT INTO game_system_changes VALUES(82,'FC27','playstyles','코너 관련 PlayStyle 문구: Dead Ball 「Set pieces are delivered with exceptional speed, curve, and accuracy.」(「세트피스를 매우 빠르고 휘어지며 정확하게 찬다」) · Precision Header 「Performs headers with greatly increased accuracy and power.」(「헤더 정확도·파워가 크게 오른다」) · Aerial Fortress는 EA 설명이 수비 공중볼 경합에 한정된다 — ⛔ 「Aerial Fortress가 공격 헤더 득점을 돕는다」는 통설은 근거 없음.','PlayStyle 문구는 EA 설명 인용(timesaver.gg 경유). 효과 크기 수치·통제 실측은 공개된 것이 없다. 타이틀 업데이트 1.0.4(10-07)까지 코너 변경 없음(가이드 서술).','빌라 코너 키커·타깃 처방에서 근거로 쓸 수 있는 것은 Dead Ball(키커)·Precision Header(타깃) 문구까지다(A, 크기 미상). Aerial Fortress를 공격 타깃 선택 근거로 쓰지 않는다.','https://timesaver.gg/blog/fc-27-corners-how-to-score-defend-aerial-fortress-myth (2026-11-04)','A(문구) — 2차 인용 경유 · 효과 크기 없음. Aerial Fortress 공격 효과 = D(기각 대상).','2026-11-04','코너 관련 PlayStyle(Dead Ball·Precision Header)');
INSERT INTO game_system_changes VALUES(83,'FC27','set_pieces','세트피스 전술 메뉴(#81 보강 · 입력·동작 세부). ⭐ 코너 입력은 두 전사가 일치한다: 메뉴 열기 D-pad ↑ · 인원 추가 ↑→↑ · 니어포스트 런 ↑→← · 파포스트 런 ↑→→ · 인원 제거 ↑→↓ (PC 화살표 조합은 전사끼리 갈린다). 수비 코너: 지역 방어 ↑→→ · 대인 방어 ↑→← (한 출처만). 프리킥(Advanced 페이지 · 기본 FK 조작은 FC26과 같다): 인원 추가·제거 · 니어/파 런 · (수비) 라인 내리기 · 오프사이드 트랩. FC26은 같은 기능이 D-pad ↓에 있었고 Edge Of Box Run · Crowd the Goalkeeper가 있었다 — 이 둘이 「인원 추가·제거」로 대체됐다. ⛔ 미확인: 인원 추가가 몇 명을 박스로 넣는지 · 기본 박스 인원 · 니어/파 런이 누구를(몇 명) 보내는지 · 지역/대인 선택이 다음 코너·경기 내내 유지되는지 · 팀 관리 화면 기본값과의 관계.','fifauteam 조작 목록(인게임 설정 → 기본 조작 전사)과 Pro Clubs HQ 조작 변경 목록이 코너 4입력(↑↑·↑←·↑→·↑↓)에서 일치. Pro Clubs HQ: 「Free kicks and corners now carry pre-set player instructions」(「프리킥과 코너에 이제 선수 지시가 미리 설정돼 있다」). EA 원문은 「the new set piece tactics interface visible」(「새 세트피스 전술 화면이 보인다」) 이미지 설명뿐. timesaver.gg는 역습 대비로 「인원 제거」로 수비수 2명을 남기라고 권한다(D).','빌라 코너 재현의 구현 가능 축 = ①니어/파 런 비중 ②박스 투입 인원(추가·제거) ③수비 지역/대인. ⚠️ 박스 인원 기본값·유지 여부를 모르므로 인게임 1회 확인(코너 한 번 → 메뉴 각 항목 → 박스 인원·러너 동선·다음 코너 유지 여부)이 필요하다 — 확인되면 C(통제 실측)로 새 행을 쓴다.','https://fifauteam.com/fc-27-controls/ · https://proclubshq.com/blog/fc27-control-changes/ · https://proclubshq.com/blog/ea-fc-corners-guide/ · https://timesaver.gg/blog/fc-27-corners-how-to-score-defend-aerial-fortress-myth · https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive (2026-11-04)','D — 인게임 조작 목록의 2차 전사 2건 일치(같은 인게임 화면 기원이라 독립 검증은 아니다). 동작(인원 수·유지)은 결손.','2026-11-04','세트피스 메뉴 입력과 미확인 동작');
INSERT INTO game_system_changes VALUES(84,'FC27','set_pieces','Avoidance·쉴딩·코너 위치잡기 세부(#79·#80 보강). ⑴ Avoidance = R1/RB 홀드 + 왼쪽 스틱 이동 — 직접 코너에서 조준 뒤 카메라가 박스로 넘어간 「공이 오기 전 창」에서만 쓴다(숏코너는 창이 없다). 조종 중인 공격수·수비수 둘 다 쓸 수 있다: 「This allows any attacker or defender you control to become more evasive」(「조종 중인 공격수나 수비수를 더 잘 빠져나가게 한다」). 효과: 혼잡 구역을 막히거나 부딪히지 않고 지나 마커를 떼어 낸다 — 「slip past opponents and try to beat them to the best spot to attack the ball」(「상대를 빠져나가 공을 공략할 최적 지점에 먼저 닿으려 한다」). ⑵ 쉴딩 = L2/LT 홀드 + 왼쪽 스틱(공격수 · 커뮤니티 전사) — 「You can also use Shielding to help hold a good position once you''ve found it.」(「좋은 위치를 찾으면 쉴딩으로 그 자리를 지킬 수 있다」). 정석 순서는 Avoidance로 공간 만들기 → 쉴딩으로 지키기. ⑶ 자동 위치 보정이 사라졌다: 「no longer moves your player toward the expected landing position of the ball」(「더 이상 선수를 공 예상 낙하 지점으로 옮겨 주지 않는다」) · 「A taller player with strong jumping, for example, may be able to meet the ball earlier in its trajectory」(「예컨대 키가 크고 점프가 좋은 선수는 궤적의 더 이른 지점에서 공을 맞출 수 있다」) · 「A player''s physical momentum also matters」(「선수의 물리적 탄력도 중요하다」). ⛔ 미공개: 창 길이 · 홀드 지속 · 쿨다운 · 스태미나 비용 · 충돌 판정 수치 · 수비수 Avoidance의 실효.','EA Gameplay Deep Dive(Avoidance 정의·입력 R1/RB 홀드) + EA Closed Beta Feedback 피치노트 2026-09-03(위치 보정 제거·키/점프/탄력 — Insider Gaming 원문 인용 경유) + fut.gg·Pro Clubs HQ(쉴딩 입력·왼쪽 스틱 병행). ⚠️ 한 출처(검색 요약)는 코너에서 R1/RB를 눌러 두 번째 선수를 키커 쪽으로 부른다(숏코너 유도)고 적었다 — 누르기(숏 호출) vs 홀드(Avoidance) 구분은 미확인(D).','Avoidance·쉴딩은 조작 축이라 전술 설정·처방에 들어가지 않는다. 다만 ⑶에 따라 빌라 코너 타깃 선택은 헤더 정확도만이 아니라 키·점프력(궤적 이른 지점 공략)을 함께 본다 — 근거 A(EA 문구 · 효과 크기 없음). 수비 코너에서 조종할 선수는 상대 주 타깃 근처의 고점프 수비수가 유리하다(추론 D).','https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive · https://insider-gaming.com/ea-fc-27-closed-beta-pitch-notes/ · https://www.fut.gg/news/how-to-use-avoidance-and-shielding-in-fc-27-corner-kicks/ · https://proclubshq.com/blog/ea-fc-corners-guide/ (2026-11-04)','A(Avoidance 정의·R1/RB 홀드·공수 겸용 · 위치 보정 제거 · 키/점프/탄력 문구) · D(쉴딩 L2/LT · 왼쪽 스틱 병행 · R1 누르기 숏 호출) · 수치 결손.','2026-11-04','Avoidance·쉴딩 세부 · 위치 자동 보정 제거');
INSERT INTO game_system_changes VALUES(85,'FC27','tactics','⭐⭐ EA 게임플레이 개발팀이 2차 Discord Q&A(10-30 · 11-02 게시 정리)에서 **수비 깊이 95 조사를 「게임플레이 팀의 현재 최우선 과제」라고 밝혔다** — 여러 접근을 **실제로 테스트 중**이다. 1차 Q&A(#69 · 10-09)의 「게임이 자리 잡을 시간을 두는 중」에서 **입장이 바뀌었다**. 다만 수비 접근(defensive approach)이 위치 시스템 전체와 묶여 있어 v1.2.0의 풀백 위치·오프사이드 인지 변경(#67)과 충돌하지 않게 신중히 시험한다고 했고 **일정은 없다**. 같은 Q&A에서 포메이션 다양성: FC26은 두 포메이션 쏠림, FC27은 UT 전체에서 **주로 8개 포메이션**이 쓰이고 상위 디비전에는 더 인기 있는 포메이션이 있다(EA 내부 데이터).','Q1 「Nerf 95 depth」(95 depth를 너프하라) · A1 「We are working on a few different approaches to make 95 depth feel balanced and fair for all players and we are currently testing them actively. This investigation is the top priority for the Gameplay team right now.」(95 depth가 모든 플레이어에게 균형 잡히고 공정하게 느껴지도록 몇 가지 다른 접근을 작업 중이며 현재 활발히 테스트하고 있다. 이 조사가 지금 게임플레이 팀의 최우선 과제다.) · 「we want to make sure that any changes we make to 95 depth don''t affect the changes we''ve made to keep the defensive line solid」(95 depth에 가하는 변경이 수비 라인을 견고하게 유지하려고 한 변경에 영향을 주지 않도록 하려 한다) · A11 「In FC 27, our data shows players are predominantly using eight formations across the entire player base in Ultimate Team.」(FC27에서 우리 데이터는 얼티밋 팀 전체 플레이어가 주로 8개 포메이션을 쓰고 있음을 보여준다.) ⚠️ Q5의 「95 depth 상대 팀이 스태미나를 더 잃는다」는 질문자 주장이고 EA는 답하지 않았다 — D.','⑴ **높은 라인 너프가 「검토」(#69)에서 「최우선·테스트 중」으로 올라갔다(A).** v1.2.0(#67)에 들어간다는 말은 없다 — 그 이후 패치 가능성이 크다(추론). ⑵ AVL FC27 전술 정본(`team_tactic_setups` #46 · Balanced/Balanced/라인 52)은 직접 대상이 아니다. 고라인·오프사이드 트랩 프리셋 강화 판단(보류 건)에는 #68·#69의 리스크 병기를 유지하고 **「다음 패치에서 깊이 상한·트랩 효율이 바뀔 공산이 더 커졌다」**로 강도를 올린다. ⑶ 포메이션 8종 분산은 메타 서술일 뿐 처방 근거가 아니다. ⑷ 3선(CDM) 역할·포커스 언급 0 → 3선 정본 재검토 사유 아님. ⛔ 처방·정본 변경 없음(#45 원칙 — 패치 적용 확인 전 바꾸지 않는다).','https://steamcommunity.com/app/4080220/discussions/0/565924099166300274/ (「FC 27 - Gameplay Developer Q&A Responses - October」 · 작성자 EA_Vendcera(EA 커뮤니티 매니저) · 2026-11-02 게시 · 공식 Discord 2차 게임플레이 Q&A(10-30) 정리 11문답)','A (EA 1차 — EA 커뮤니티 매니저가 개발자 답변을 정리한 공식 전사 · 2026-11-04 직접 열람) · 단일 공식 정리라 교차검증 대상 없음(번역본·현지어 정리 미발견)','2026-11-04','수비 깊이 95가 최우선 과제로(2차 Q&A)');
INSERT INTO game_system_changes VALUES(86,'FC27','engine','EA 2차 Discord Q&A(10-30)의 패스·전환 답변: ⑴ **땅볼 패스가 리시버를 예상 밖 방향으로 리드하는 경우**와 **측면으로 가로지르는 스루 패스가 예상과 다른 리시버를 겨냥하는 경우**를 인정하고 조사 중(저수준 패스 시스템이라 신중) ⑵ **스루 패스 보정 축소(#71) 때문에 플레이어가 스루 패스를 덜 쓰고 드리븐(핑) 패스를 더 쓰는** 밸런스 이동을 EA가 데이터로 확인하고 감시 중 — 패스 튜닝 약속은 없음 ⑶ 선수 전환은 L1/LB와 오른쪽 스틱을 **별개 메커니즘으로 따로 조사** 중(v1.2.0의 루즈볼 전환 수정 #67과 별개). 모두 일정 없음.','A2 「We do see some cases where ground passes lead the receiver in an unexpected way, and some cases where through passes made laterally across the pitch target a different receiver than expected.」(땅볼 패스가 리시버를 예상 밖 방식으로 리드하는 경우와, 측면으로 가로지르는 스루 패스가 예상과 다른 리시버를 겨냥하는 경우가 실제로 있다.) · A4 「Because of the changes to through pass assistance in FC 27, players are using through passes less and driven passes more, which is a shift in game balance that we are monitoring closely.」(FC27의 스루 패스 보정 변경 때문에 플레이어가 스루 패스를 덜, 드리븐 패스를 더 쓰고 있고, 이는 우리가 면밀히 감시하는 게임 밸런스 이동이다.) · A5 「Right stick switching works differently from L1/LB switching, so we have to approach these two mechanics independently in our investigations.」(오른쪽 스틱 전환은 L1/LB 전환과 다르게 작동하므로 두 메커니즘을 조사에서 따로 다뤄야 한다.)','⑴ #71(스루 패스 수동화 · FC26→FC27 버전 차이)의 **결과가 EA 데이터로 확인됐다**(A) — 에메리식 수직 전환을 FC27에서 재현할 때 **스루 패스보다 드리븐 패스(핑드 패스 · #22·#60 PlayStyle 축)가 실효 수단**이라는 판단을 지지한다. 다만 핑 패스 너프 요구가 있고 EA가 「감시 중」이라 패치 리스크가 있다. ⑵ 측면 가로지르는 스루 패스의 리시버 오지정은 측면 전환 처방(Wide 빌드업)을 실행할 때의 조작 리스크로만 기록한다. ⑶ 3선 역할 무관.','https://steamcommunity.com/app/4080220/discussions/0/565924099166300274/ (「FC 27 - Gameplay Developer Q&A Responses - October」 · 작성자 EA_Vendcera(EA 커뮤니티 매니저) · 2026-11-02 게시 · 공식 Discord 2차 게임플레이 Q&A(10-30) 정리 11문답)','A (EA 1차 — EA 커뮤니티 매니저가 개발자 답변을 정리한 공식 전사 · 2026-11-04 직접 열람) · 단일 공식 정리라 교차검증 대상 없음(번역본·현지어 정리 미발견)','2026-11-04','땅볼·스루 패스 리시버 겨냥 문제 조사');
INSERT INTO game_system_changes VALUES(87,'FC27','goalkeeping','EA 2차 Discord Q&A(10-30)에서 **니어포스트 슛이 일부 각도에서 지나치게 효과적**이라고 인정하고 **슈팅과 GK 위치잡기 양쪽**에서 관련 해법을 작업 중이라고 답했다(일정 없음). #68의 「슈팅 정확도·GK 위치잡기」 조사 항목의 구체 증상이며 **v1.2.0 항목에는 없다**.','Q3 「So no nerf to low driven near post?」(그럼 낮게 깔아 차는 니어포스트 슛 너프는 없나?) · A3 「We are aware that near post shots are too effective from some angles and we are working on some related solutions in both shooting and goalkeeper positioning to address this.」(일부 각도에서 니어포스트 슛이 지나치게 효과적이라는 것을 알고 있으며, 이를 해결하려고 슈팅과 골키퍼 위치잡기 양쪽에서 관련 해법을 작업 중이다.)','⑴ FC27 v1.1.0 시점 **GK 니어포스트 약점은 EA 인정 사실(A)** — #73(EA 1차 자료의 GK 변경 서술 0건)·#78(FC26 TU 1.1.0의 니어포스트 반응 개선 전례)과 함께 본다. 수정 전까지 GK 카드 비교에서 니어포스트 실점은 **카드 차이보다 엔진 공통 약점**일 수 있다. ⑵ GK 선택·진화 처방은 바꾸지 않는다(수정 예고 · 일정 없음). ⑶ 3선 역할 무관.','https://steamcommunity.com/app/4080220/discussions/0/565924099166300274/ (「FC 27 - Gameplay Developer Q&A Responses - October」 · 작성자 EA_Vendcera(EA 커뮤니티 매니저) · 2026-11-02 게시 · 공식 Discord 2차 게임플레이 Q&A(10-30) 정리 11문답)','A (EA 1차 — EA 커뮤니티 매니저가 개발자 답변을 정리한 공식 전사 · 2026-11-04 직접 열람) · 단일 공식 정리라 교차검증 대상 없음(번역본·현지어 정리 미발견)','2026-11-04','니어포스트 슛 과효 인정');
INSERT INTO game_system_changes VALUES(88,'FC27','attributes','EA 2차 Discord Q&A(10-30)에서 **공격수가 수비수보다 태클·인터셉트를 잘하는 등 포지션에 비해 지나치게 효과적인 상황**을 해결하려고 「적극적으로 작업 중」이라고 답했다(설계 원칙: 선수는 실제 포지션에 맞게 느껴져야 한다). 키 큰 선수와 작은 선수의 몸싸움 균형도 다시 조사 중이라고 했다(#70의 후속 · 같은 입장 반복). 일정 없음.','A6 「One of the design principles we have every year is that players should feel appropriate for the position they play in the real world.」(매년 지키는 설계 원칙 하나는 선수가 실제로 뛰는 포지션에 맞게 느껴져야 한다는 것이다.) · 「When we have situations where players are more effective than expected, like attackers making tackles, it is something we want to address.」(공격수가 태클을 해내는 것처럼 선수가 기대보다 효과적인 상황이 있으면 우리가 고치고 싶은 부분이다.) · A8 「We are currently investigating the balance of tall vs. short players, especially in physical challenges.」(특히 몸싸움에서 키 큰 선수와 작은 선수의 균형을 현재 조사하고 있다.)','⑴ #46(저수비 스탯 선수의 자동 인터셉트)에 대해 1차 Q&A(#71)는 「균형을 익히는 중」이라는 일반론이었는데, 이번에는 **「적극 작업 중」으로 수정 의사를 밝혔다(A · 일정 없음)**. ⇒ #46 impact(한시적)의 「수정 예고 없음」은 **「수정 의사 표명 · 일정 없음」으로 읽는다**(기존 행은 고치지 않고 이 행으로 덧붙인다). ⑵ 3선(CDM) 함의: 수정이 들어가면 **수비 스탯(인터셉트·태클·수비 인지)의 상대 가치가 오른다** — 볼 탈취형 3선(카마라 dm_holding/Defend)에 불리하지 않은 방향이다. 단 역할·포커스 동작 변경이 아니므로 **3선 정본 재검토 사유는 아니다**(사용자 판단 사안 · 정본 변경 없음). ⑶ 체격 균형은 #70 결론(힘만 보는 피지컬 진화 가성비 한 단계 낮춤) 유지.','https://steamcommunity.com/app/4080220/discussions/0/565924099166300274/ (「FC 27 - Gameplay Developer Q&A Responses - October」 · 작성자 EA_Vendcera(EA 커뮤니티 매니저) · 2026-11-02 게시 · 공식 Discord 2차 게임플레이 Q&A(10-30) 정리 11문답)','A (EA 1차 — EA 커뮤니티 매니저가 개발자 답변을 정리한 공식 전사 · 2026-11-04 직접 열람) · 단일 공식 정리라 교차검증 대상 없음(번역본·현지어 정리 미발견)','2026-11-04','포지션에 안 맞는 태클·인터셉트 과효 수정 중');
INSERT INTO game_system_changes VALUES(89,'FC27','evolution','EA FUT Q&A(10-14 게시 정리)에서 **FC27 진화 상향 폭을 지나치게 줄였다고 인정했다** — FC26에서 진화 쪽으로 쏠린 균형을 출시 때 의도적으로 낮췄는데 「너무 많이 당긴 것 같다」고 했고, 목표는 **평균 플레이어 스쿼드에 진화 카드 몇 장이 늘 있는 상태**라고 밝혔다. 또 예년처럼 시즌이 진행되면서 **동시 진행 진화 슬롯 수를 늘릴 계획**이다(일정 없음).','A2 「in FC26, we felt that balance had shifted too heavily towards Evolutions, so we made some changes at launch to give other progression systems, including the Transfer Market and campaigns, more room to shine. That said, we recognize that we''ve likely pulled back a bit too far.」(FC26에서는 균형이 진화 쪽으로 너무 기울었다고 느껴 출시 때 이적 시장·캠페인 등 다른 성장 경로가 빛날 여지를 주도록 바꿨다. 다만 아마 너무 많이 당긴 것 같다고 인정한다.) · 「We think the ideal balance is that the average player has a few Evolutions in their squad at any given time.」(이상적인 균형은 평균적인 플레이어의 스쿼드에 언제나 진화 카드가 몇 장 있는 상태라고 본다.) · A7 「we have plans to increase the number of Evolutions you can have active and make progress on simultaneously as the year goes on.」(시즌이 진행되면서 동시에 활성화·진행할 수 있는 진화 수를 늘릴 계획이 있다.)','⑴ ⭐ 버전 차이(A): **FC27 진화는 FC26보다 의도적으로 약하게 출발**했다 — FC26 진화 처방·가성비 판단을 FC27로 전용하지 않는다. ⑵ EA가 상향 의사를 밝혔다 → 시즌 중반 이후 진화 카탈로그의 상한이 올라갈 공산이 있다(추론). 지금 약한 진화에 핵심 카드를 소모하는 판단은 「더 강한 진화가 나올 수 있다」를 리스크로 병기한다. ⑶ 진화 슬롯 확대는 진행 동시성 계획에 영향(일정 없음). 3선 역할 무관.','https://steamcommunity.com/app/4080220/discussions/0/562544805318581878/ (「FC 27 - FUT Developer Q&A Responses」 · 작성자 EA_Vendcera(EA 커뮤니티 매니저) · 2026-10-14 게시 · 공식 Discord FUT Q&A 정리 21문답)','A (EA 1차 — EA 커뮤니티 매니저가 개발자 답변을 정리한 공식 전사 · 2026-11-04 직접 열람) · 단일 공식 정리 · 일정 약속 없음','2026-11-04','진화 상향 폭 과소 인정 · 슬롯 확대 계획');
INSERT INTO game_system_changes VALUES(90,'FC27','tactics','EA FUT Q&A(10-14 게시 정리)에서 **경기 중 커스텀 전술을 바꿀 때 선수 포지션이 바뀌는 버그**(FUT·감독 커리어에서 새 포메이션으로 전환할 때 선수가 제자리를 벗어나 배치됨)를 「레이더에 있다 · 해결 방법을 보고 있다」고 인정했다(일정 없음). v1.1.0(#64)의 **새 전술 저장 버그 수정과는 다른 증상**이다(저장이 아니라 경기 중 전환).','Q11 「Fix the issue where players change positions when switching between Custom Tactics during a match in Ultimate Team」(얼티밋 팀에서 경기 중 커스텀 전술을 전환하면 선수 포지션이 바뀌는 문제를 고쳐 달라) · A11 「This is on our radar, and we''re looking into how we can address it.」(이 문제를 인지하고 있으며 어떻게 해결할지 살펴보고 있다.) · Q14 「happens to me on manager career and fut whenever I switch to new formations」(감독 커리어와 FUT에서 새 포메이션으로 바꿀 때마다 일어난다) · A14 같은 답.','⑴ AVL 경기 프리셋(`match_game_setups`)처럼 **경기 중 커스텀 전술을 갈아끼우는 운용**에서 전환 직후 선수 배치가 정본과 어긋날 수 있다(A · v1.1.0 수정 대상 아님). ⇒ 전환 직후 포메이션 화면에서 슬롯을 확인하는 절차를 권장으로 병기한다. ⑵ 3선 함의: 전환 시 RDM/LDM 자리가 뒤바뀌면 카마라(RDM dm_holding/Defend)·고메스(LDM dm_dlp/Roaming) 배치가 뒤집힐 수 있다 — **역할 동작 변경이 아니라 배치 버그**이므로 정본 재검토 사유는 아니다(정본 변경 없음). ⑶ 이 행은 10-14 게시 글을 11-04에야 검토한 것이다 — Steam Q&A 고정글은 EA 뉴스 색인 밖이라 `patch_watch_index.py`가 잡지 못한다.','https://steamcommunity.com/app/4080220/discussions/0/562544805318581878/ (「FC 27 - FUT Developer Q&A Responses」 · 작성자 EA_Vendcera(EA 커뮤니티 매니저) · 2026-10-14 게시 · 공식 Discord FUT Q&A 정리 21문답)','A (EA 1차 — EA 커뮤니티 매니저가 개발자 답변을 정리한 공식 전사 · 2026-11-04 직접 열람) · 단일 공식 정리 · 일정 약속 없음','2026-11-04','경기 중 전술 전환 시 포지션 버그 인정');
INSERT INTO game_system_changes VALUES(91,'FC27','evolution','⑴ 진화 요구조건의 포지션(예: Channel Surfer [SP 11] 「LM, LW」)은 **보조 포지션도 인정**한다 — 주 포지션 CAM(보조 RM·CM·LM·RW·LW)인 지모알로바 카드가 적용 대상에 들었다. ⑵ 인게임 「진화 제거」 직후에는 OVR 조건을 새로 만족해도 **진화 선택 목록에 바로 뜨지 않았고**, 재접속한 뒤에 떴다(EA 쪽 카드 상태 갱신 지연으로 보임).','사용자 인게임 실측 2026-11-04 — 마녀의 시간(Witching Hour) 제거로 OVR 81→80이 된 지모알로바(주 CAM)에게 측면질주(Channel Surfer)가 처음엔 선택 불가 → 재접속 후 선택·시작. fut.gg 적용 가능 선수 목록(fc_evolution_eligibility)에도 이 카드가 올라 있었다(보조 포지션 기준과 정합).','진화 후보를 고를 때 보조 포지션까지 넣어 조건을 판정해도 된다(진화 화면 후보 계산과 정합). 진화를 제거한 직후 「대상이 아니다」로 보이면 재접속 뒤 다시 확인한다 — 원장에 시작을 적기 전에 인게임 선택이 됐는지 확인할 것(이번에 한 번 미리 적었다가 무효 처리했다).','사용자 인게임 확인(2026-11-04) · 원장 fut_evolution_log(지모알로바 #146 · Witching Hour 제거 · Channel Surfer 시작)','C — 통제 실측 1건(카드 1장 · 진화 1종). 주 포지션만 맞는 다른 진화에서도 같은지는 미확인.','2026-11-04','진화 포지션 조건은 보조 포지션도 인정 · 제거 직후엔 재접속 필요');
INSERT INTO game_system_changes VALUES(92,'FC27','attributes','민첩성(Agility)이 하는 일을 EA가 문서로 밝힌 것은 셋이다. ⑴ 드리블 애니메이션이 **재생되는 속도**(드리블·민첩·반응력) ⑵ 드리블 애니메이션 **사이를 넘어가는 속도**(드리블·민첩·균형·반응력) ⑶ **AcceleRATE 유형 판정**(키·민첩·힘). FC27에서는 ⑷ **오프밸런스 드리블 입력**(균형·민첩·드리블 · #24)이 더해졌다. ⛔ 방향 전환 반경·턴 속도·수비 자세(조키) 회전에 민첩성이 쓰인다는 EA 문서는 **0건**이다(커뮤니티 체감 「가볍다/무겁다」뿐 · D). 조키 속도는 스프린트 속도와 무관하고 수비 인지가 정한다(FIFA 23).','「Dribbling, Agility and Reactions - How quickly animations play out.」(드리블·민첩·반응력 — 애니메이션이 얼마나 빨리 재생되는가) · 「Dribbling, Agility, Balance and Reactions - How quickly the ball carrier can transition between different dribbling animations.」(드리블·민첩·균형·반응력 — 볼 운반자가 서로 다른 드리블 애니메이션 사이를 얼마나 빨리 넘어가는가) · 「with higher Attributes having a more positive impact.」(높은 능력치일수록 더 긍정적인 영향을 준다) · 「The Sprint Speed Attribute does not impact Jockey speed.」(스프린트 속도 능력치는 조키 속도에 영향을 주지 않는다) · Explosive 조건(FIFA 23): 「Agility >= 65」「(Agility - Strength) >= 15」「Acceleration >= 74」「Height <= 180 cm」(민첩 65 이상 · 민첩−힘 15 이상 · 가속 74 이상 · 키 180cm 이하) → FC26에서 ≥10·≥80으로 바뀌었다(버전마다 바뀐 전례).','케미 스타일 비교에서 민첩 상승은 「드리블 동작이 빨라지고 동작 전환이 짧아지는」 축으로 읽는다 — 방향 전환·수비 회전 효과로 쓰지 않는다. 만잠비 Artist(민첩 90→99) vs Maestro(볼컨트롤 89→95)는 둘 다 드리블 운반 축이지만, 민첩 쪽 근거만 EA 문서(FIFA 23 · FC27 이월 미확인)가 있다.','EA FIFA 23 Pitch Notes – Gameplay Deep Dive https://www.ea.com/games/battlefield/news/pitch-notes-fifa-23-gameplay-deep-dive (2026-11-05 직접 열람 · 원문 일치 확인) · FC27 Deep Dive https://www.ea.com/games/ea-sports-fc/fc-27/news/pitch-notes-fc27-gameplay-deep-dive','A — EA 1차지만 **FIFA 23 문서**다. FC27 문서에는 ⑴⑵ 문구가 없다(재확인도 부정도 없음) — FC27로 이월 적용은 추정. ⑷만 FC27 A. 다국어 정리본(es·de·ja)은 같은 EA 문서의 번역 복제라 교차검증이 아니다.','2026-11-05','민첩성 = 드리블 애니메이션 속도·전환 속도·가속 유형(FIFA 23 원문 · FC27 미재확인)');
INSERT INTO game_system_changes VALUES(93,'FC27','attributes','능력치를 올렸을 때 효과가 **선형인지·체감(로그형)인지·S자인지·계단형인지 판정할 근거가 없다**(FC27 · 출시 6주차 재조사). 알려진 것은 구조뿐이다: ⑴ EA는 「높을수록 좋다」만 말하고 곡선 모양을 밝힌 적이 없다(A) ⑵ 게임 파일에는 속력이 「능력치→속도 관계 커브 + 최솟값·최댓값 상한」으로 정의돼 있다(B · FIFA 20·FC25 모드 커뮤니티 · 커브 모양 미공개) — 커브가 따로 있다는 것은 **순수 선형이 아닐 수 있다**는 뜻일 뿐이다 ⑶ 70→79 대 90→99를 비교한 통제 실측은 전 버전 0건(C 없음). ⚠️ 이미 확인된 **계단형**은 별개 장치다: AcceleRATE 유형 조건(#5·#12)·오프밸런스 「필요한 수치」(#24)·Team Press 수비 서드 무효(A). 「85 넘으면 다르다」「129부터 오른다」류는 D(FC온라인 체감 포함 · 다른 게임).','Evoweb FIFA 20 Gameplay Lab: `ATTR_SprintSpeedTbl_MinMax_Normal` [0]=0.37(느린 선수) [1]=0.45(빠른 선수) · 표 21칸은 「could each correspond to a range of player speed attribute」(각각 속력 능력치 구간에 대응할 수 있다 — 작성자 미검증). Evoweb 스프린트 속도 글타래: 「attr_sprintspeed is sprint speed/player attribute relation curve」(능력치↔속도 관계 커브) · 「attr_sprintspeedtblminmax are top/bottom hard caps」(위·아래 고정 상한). EA FC27(Sam Rivera · Red Bull 전재): 「for a PlayStyle to give you a bonus of around 5 to 10 per cent」(PlayStyle 보너스는 대략 5~10%) · 「An 80-rated striker with Finesse Shot will never be better than a 99-rated striker」(피네스 샷을 가진 80 공격수가 99 공격수보다 나을 일은 없다) — 이것은 능력치 곡선이 아니라 PlayStyle 크기다. FC27 Deep Dive: 「Shot velocity now scales purely based on core shooting Attributes and input power」(슈팅 속도는 이제 핵심 슈팅 능력치와 입력 파워로만 비례한다 — 모양 미기재).','커널·케미 점수는 지금처럼 **선형 가중(가중 × 실제 상승분)**을 유지한다 — 다른 모양을 고를 근거가 없다(이 가정은 D가 아니라 「미상 위의 기본값」). 99 근처 상승을 할인하지 않는다. 계단형으로 확인된 것(AcceleRATE·PlayStyle 발동 문턱)만 따로 판정한다. 새 실측(C)이 나오면 이 행에 이어 쓴다.','https://evoweb.uk/threads/evoweb-gameplay-lab-fifa-20-frostbite-fifas.82886/ · https://evoweb.uk/threads/sprint-speed.101772/ · https://www.redbull.com/us-en/ea-fc-27-guide-tips · EA FC27 Deep Dive · 서브에이전트 다국어 조사(en·ko·ja·es·de·pt · fr·it 미실시 · SoccerGaming 403)','구조만 B(FIFA 20·FC25 게임 파일 · 모양 미공개 · 작성자 미검증) · 곡선 모양 = 근거 없음(A·B·C 0건) · 계단형 체감 주장은 D. 2026-09-21 리서치 §6 「임계값·구간」의 출시 후 재확인.','2026-11-05','스탯 상승은 선형인가 — 곡선 모양 미상(구조는 「커브+상하한」)');
INSERT INTO game_system_changes VALUES(94,'FC27','attributes','볼컨트롤(Ball Control)의 작용을 EA가 문서로 밝힌 것은 셋이다. ⑴ **드리블 터치의 정확도**(드리블·볼컨트롤) ⑵ **드리블 중 공이 몸에 붙어 있는 거리**(드리블·볼컨트롤) — 둘 다 FIFA 23 기술 드리블 속성표 ⑶ **퍼스트 터치 난이도**(볼컨트롤·차단·침착 복합 · FC26 · #23). ⛔ 볼컨트롤이 **들어가지 않는** 것: 드리블 동작 재생 속도·동작 전환 속도(#92 · 드리블·민첩·균형·반응력) · 드리블 중 유지 속도(드리블·반응력) · FC27 오프밸런스 드리블(#24 · 균형·민첩·드리블). FC27 1차 문서에는 볼컨트롤 기능 설명이 0회다(9월 전수 스캔) — 전부 이전 버전 문서의 이월 추정.','FIFA 23 기술 드리블 속성표 머리말 「Here''s a list of which Attributes can impact aspects of Technical Dribbling the most」(기술 드리블의 각 측면에 가장 크게 영향을 주는 속성 목록) — 「Dribbling and Ball Control - Precision of the dribble touch.」(드리블·볼컨트롤 — 드리블 터치의 정확도) · 「Dribbling and Ball Control - How close or far the ball can stay to the dribbler.」(드리블·볼컨트롤 — 공이 드리블러에게 얼마나 가깝게 또는 멀리 머무는가) · 「Dribbling and Reactions - How much speed the ball carrier maintains while dribbling.」(드리블·반응력 — 드리블 중 볼 운반자가 속도를 얼마나 유지하는가). 퍼스트 터치는 FC26 딥다이브(#23) 원문.','케미 스타일 비교에서 볼컨트롤 상승은 「터치가 정확하고 공이 몸에 붙는」 축(+ 퍼스트 터치)으로 읽는다 — 민첩·반응력의 「동작 속도·전환」 축과 겹치지 않는 별개 축이다. 만잠비 Maestro(볼컨트롤 89→95)는 이 축, Artist(민첩 90→99·반응력 87→93)는 동작 속도 축에서 앞선다. 드리블(+3)은 두 스타일이 같다.','EA FIFA 23 Pitch Notes – Gameplay Deep Dive https://www.ea.com/games/battlefield/news/pitch-notes-fifa-23-gameplay-deep-dive (2026-11-05 직접 열람 · 원문 일치) · EA FC26 Gameplay Deep Dive(#23)','A — EA 1차지만 ⑴⑵는 **FIFA 23**, ⑶은 **FC26** 문서다. FC27 문서는 볼컨트롤을 설명하지 않는다(재확인·부정 모두 없음) → FC27 이월 적용은 추정. 각 스탯의 비중·곡선 모양은 미공개(#93).','2026-11-05','볼컨트롤 = 드리블 터치 정확도·공과의 거리 + 퍼스트 터치(FIFA 23·FC26 원문 · FC27 미재확인)');
